/**
 * Glossary of trading terms. Each entry can be referenced in lessons with
 *   <Term id="spread">the spread</Term>
 * and appears on the /glossary page.
 */
export interface GlossaryEntry {
  id: string;        // kebab-case, used in URLs and <Term id>
  term: string;      // display name
  short: string;     // one sentence, shown on hover
  long?: string;     // 2-4 sentences, shown on the glossary page
  related?: string[];// ids of related entries
  lesson?: string;   // path of the best lesson, e.g. /learn/m00-what-is-a-market/07-bid-ask-spread
}

export const GLOSSARY: GlossaryEntry[] = [
  { id: 'accumulation', term: 'Accumulation', short: 'A quiet phase where large buyers build positions without pushing price up.', long: 'In the Wyckoff model this is the first of four phases: price goes sideways at low levels while informed money absorbs supply. It looks boring, which is the point, because excitement would raise the price they are paying. Accumulation ends when price breaks out into markup.', related: ['wyckoff', 'markup', 'distribution'], lesson: '/learn/m03-market-structure/09-market-cycles-wyckoff' },
  { id: 'adx', term: 'ADX', short: 'A 0 to 100 reading of how strongly a market is trending, ignoring direction.', long: 'Readings under 20 usually mean chop and readings over 25 mean a real trend is present. ADX does not tell you up or down, only how organised the move is. It is most useful as a switch: trend strategies above 25, range strategies below 20.', related: ['trend', 'range', 'indicator'], lesson: '/learn/m05-indicators/11-adx-and-trend-strength' },
  { id: 'after-hours', term: 'After-Hours', short: 'Trading that continues after the official close, again on thin volume.', long: 'Companies often report earnings just after the bell, so a stock can jump ten percent while the regular market sleeps. Prices set here frequently do not hold into the next open. Treat after-hours quotes as a rough poll rather than a firm valuation.', related: ['pre-market', 'earnings', 'gap'], lesson: '/learn/m00-what-is-a-market/08-market-hours-and-sessions' },
  { id: 'ask', term: 'Ask', short: 'The lowest price a seller is currently willing to accept.', long: 'The ask, sometimes called the offer, is the price you pay if you buy immediately. It is always at or above the bid. Beginners are surprised that buying and instantly selling loses money: that loss is the spread, and it is the market maker getting paid.', related: ['bid', 'spread', 'market-order'], lesson: '/learn/m00-what-is-a-market/07-bid-ask-spread' },
  { id: 'atr', term: 'ATR', short: 'Average True Range: the typical distance a price travels in one period.', long: 'If a stock has an ATR of $2 on the daily chart, a stop placed 30 cents away will be hit by ordinary noise almost immediately. Many traders size stops at one and a half or two ATR from entry. It is the single most useful number for adapting your plan to different instruments.', related: ['volatility', 'stop-loss', 'position-sizing'], lesson: '/learn/m05-indicators/08-atr' },
  { id: 'averaging-down', term: 'Averaging Down', short: 'Buying more of a losing position to lower your average entry price.', long: 'It feels clever because the average price improves, but it increases risk in a trade that is already proving you wrong. Buy 100 at 50 and 100 more at 40 and your average is 45, with twice the exposure to a falling stock. Investors can sometimes justify it; traders with stops almost never can.', related: ['martingale', 'sunk-cost', 'risk-management'], lesson: '/learn/m07-risk-management/10-never-average-down' },
  { id: 'backtesting', term: 'Backtesting', short: 'Testing your rules against historical data to see how they would have performed.', long: 'Done well, it tells you the expectancy, win rate and worst drawdown you should expect. Done badly, it tells you a beautiful story about a strategy that only works on the past. Be strict about including costs and about not peeking at candles that had not closed yet.', related: ['forward-testing', 'overfitting', 'sample-size'], lesson: '/learn/m09-strategies/09-backtesting-and-forward-testing' },
  { id: 'backwardation', term: 'Backwardation', short: 'When future-dated contracts cost less than the current price.', long: 'It usually signals a shortage right now: buyers will pay a premium for immediate delivery. Rolling contracts forward in backwardation adds a small gain instead of a cost. Markets can flip between contango and backwardation as supply conditions change.', related: ['contango', 'rollover', 'commodity'], lesson: '/learn/m11-derivatives-and-other-markets/04-futures' },
  { id: 'balance-sheet', term: 'Balance Sheet', short: 'A snapshot of what a company owns and what it owes on a given day.', long: 'Assets on one side, liabilities and equity on the other, and the two must balance. It is where you find debt levels and cash reserves, which decide whether a company can survive a bad year. A profitable company with too much short-term debt can still fail.', related: ['cash-flow', 'earnings', 'fundamental-analysis'], lesson: '/learn/m10-fundamentals-and-macro/02-earnings-and-financial-statements' },
  { id: 'bear-market', term: 'Bear Market', short: 'A long stretch where prices generally fall and sellers stay in control.', long: 'Commonly marked as a fall of twenty percent or more from a high. Bear markets have vicious rallies that look like recoveries and then fail, which traps buyers repeatedly. Falls tend to be faster than rises, because fear acts more quickly than greed.', related: ['bull-market', 'downtrend', 'markdown'], lesson: '/learn/m00-what-is-a-market/03-why-prices-move' },
  { id: 'bid', term: 'Bid', short: 'The highest price a buyer is currently willing to pay.', long: 'The bid is the price you receive if you sell right now with a market order. It sits below the ask, and the two together are the quote. If the bid is 49.98 and you own shares, 49.98 is the honest value of your position, not the last traded price.', related: ['ask', 'spread', 'order-book'], lesson: '/learn/m00-what-is-a-market/07-bid-ask-spread' },
  { id: 'body', term: 'Candle Body', short: 'The thick part of a candle, stretching from the open to the close.', long: 'A long body means one side dominated the whole period; a short body means the fight ended near where it started. On a daily chart, a body of three dollars on a fifty dollar stock is a serious statement of intent. Body size is the quickest read of conviction on any chart.', related: ['wick', 'marubozu', 'spinning-top'], lesson: '/learn/m01-reading-price/04-bullish-vs-bearish' },
  { id: 'bollinger-bands', term: 'Bollinger Bands', short: 'A moving average with bands placed two standard deviations above and below.', long: 'The bands widen when volatility rises and pinch together when it falls, so they map the current normal range. Price touching the upper band means it is statistically stretched, not that it must fall. In strong trends price can walk the band for a long time.', related: ['squeeze', 'volatility', 'overlay'], lesson: '/learn/m05-indicators/07-bollinger-bands' },
  { id: 'bracket-order', term: 'Bracket Order', short: 'An entry sent together with its stop loss and its take profit.', long: 'The whole trade is defined before you are emotionally involved, which is the real benefit. If the entry fills at 100, the stop at 98 and the target at 106 go live automatically. When one exit triggers, the other is cancelled, because they are linked as an OCO pair.', related: ['oco', 'stop-loss', 'take-profit'], lesson: '/learn/m06-orders-and-execution/03-bracket-and-oco' },
  { id: 'breakout', term: 'Breakout', short: 'Price pushing decisively out of a range or through a key level.', long: 'A real breakout usually comes with a jump in volume and a candle that closes beyond the level rather than just poking through. If a stock has capped at 75 for weeks and closes at 77 on double volume, that is a breakout worth respecting. Many traders wait for the retest instead of chasing the first candle.', related: ['fakeout', 'retest', 'volume'], lesson: '/learn/m03-market-structure/06-breakouts-and-fakeouts' },
  { id: 'broker', term: 'Broker', short: 'The company that holds your money and sends your orders to the exchange.', long: 'A broker is your door into the market. You deposit cash, click buy, and the broker routes that order onwards and keeps a record of what you own. Brokers differ in fees, execution quality, tools and, most importantly, in which regulator is watching them.', related: ['commission', 'regulation', 'exchange'], lesson: '/learn/m00-what-is-a-market/05-the-players' },
  { id: 'bull-market', term: 'Bull Market', short: 'A long stretch where prices generally rise and buyers stay in control.', long: 'The usual rough definition is a rise of twenty percent or more from a major low, sustained over months. In a bull market pullbacks get bought and bad news is shrugged off. Strategies that buy dips look genius here, which is exactly why traders are unprepared when the weather changes.', related: ['bear-market', 'uptrend', 'markup'], lesson: '/learn/m00-what-is-a-market/03-why-prices-move' },
  { id: 'call-option', term: 'Call Option', short: 'The right to buy something at a fixed price before a set date.', long: 'Buy a 100 strike call for $3 and you profit above $103 at expiry, while your loss is capped at the $3 paid. Each contract normally covers 100 shares, so that $3 is really $300. Calls give you upside exposure for a fraction of the cost of the shares, in exchange for a deadline.', related: ['put-option', 'strike-price', 'premium'], lesson: '/learn/m11-derivatives-and-other-markets/01-options-basics' },
  { id: 'candlestick', term: 'Candlestick', short: 'A chart symbol showing the open, high, low and close of one time period.', long: 'Japanese rice traders invented candles centuries ago and they won because one glance gives you four prices and the mood of the period. The coloured body spans open to close; the thin wicks reach the extremes. Every candle is a small battle report between buyers and sellers.', related: ['body', 'wick', 'timeframe'], lesson: '/learn/m01-reading-price/03-anatomy-of-a-candle' },
  { id: 'cash-flow', term: 'Cash Flow', short: 'The actual money moving in and out of a business.', long: 'Profit is an accounting opinion; cash flow is closer to a fact. A company can report profits while burning cash, because sales booked on credit count as revenue before anyone pays. Free cash flow, what is left after running and maintaining the business, is the number investors watch most.', related: ['balance-sheet', 'revenue', 'earnings'], lesson: '/learn/m10-fundamentals-and-macro/02-earnings-and-financial-statements' },
  { id: 'catalyst', term: 'Catalyst', short: 'A specific event that gives traders a reason to reprice something quickly.', long: 'Earnings, product launches, rate decisions, takeovers and lawsuits all qualify. A clean technical setup with a catalyst behind it attracts far more participation than one without. The flip side is that holding through a scheduled catalyst is a bet on a coin toss with a wide range.', related: ['earnings', 'guidance', 'gap'], lesson: '/learn/m09-strategies/07-momentum-and-news' },
  { id: 'central-bank', term: 'Central Bank', short: 'The institution that sets a country base interest rate and money supply.', long: 'The Federal Reserve, European Central Bank and Bank of England are the best known. Their job is usually to keep inflation near a target, often two percent, while protecting employment. Their statements are parsed word by word because a single adjective can move trillions.', related: ['interest-rate', 'fomc', 'inflation'], lesson: '/learn/m10-fundamentals-and-macro/04-interest-rates-and-central-banks' },
  { id: 'cfd', term: 'CFD', short: 'A contract for difference: you settle the price change without owning the asset.', long: 'CFDs give easy leveraged access to many markets from one account, which is why they are popular outside the United States, where they are banned for retail traders. Costs include the spread, commission and an overnight financing charge. Published broker statistics routinely show most CFD accounts losing money.', related: ['derivative', 'leverage', 'regulation'], lesson: '/learn/m11-derivatives-and-other-markets/07-etfs-and-leveraged-products' },
  { id: 'channel', term: 'Channel', short: 'Two parallel lines containing price as it trends, like a road with kerbs.', long: 'Draw the trendline first, then copy it to the opposite side of the move. Price bouncing between the rails gives you a rough map of where rallies stall and dips stop. A strong break outside the channel often signals either acceleration or exhaustion, so context still decides.', related: ['trendline', 'range', 'breakout'], lesson: '/learn/m03-market-structure/04-trendlines-and-channels' },
  { id: 'close', term: 'Close', short: 'The final traded price of a candle or session.', long: 'The close is the most important of the four prices because it is the number both sides agreed to end on. Most indicators, from moving averages to RSI, are calculated on closes only. A break of a level that fails to close beyond it is usually not a break at all.', related: ['open', 'candlestick', 'confirmation'], lesson: '/learn/m01-reading-price/03-anatomy-of-a-candle' },
  { id: 'commission', term: 'Commission', short: 'The fee your broker charges for executing a trade.', long: 'It may be a flat amount, a per-share rate, or zero with the cost hidden in worse execution. Commissions matter most to frequent traders: at $1 per trade, ten trades a day costs $2,500 a year. Always calculate your strategy costs on a round trip, both in and out.', related: ['spread', 'broker', 'settlement'], lesson: '/learn/m06-orders-and-execution/09-fees-commissions-settlement' },
  { id: 'commodity', term: 'Commodity', short: 'A physical raw material such as oil, gold, wheat or copper that trades on an exchange.', long: 'Commodities are interchangeable: one barrel of a given grade of crude is the same as any other, so only price separates them. Most traders access them through futures contracts or ETFs rather than taking delivery of actual barrels. Their prices respond to weather, wars, storage costs and the strength of the dollar.', related: ['futures', 'contango', 'backwardation'], lesson: '/learn/m00-what-is-a-market/06-what-can-you-trade' },
  { id: 'confirmation', term: 'Confirmation', short: 'Waiting for extra evidence before acting on a pattern or signal.', long: 'A hammer becomes a trade only when the next candle closes above its high; a breakout becomes real when a candle closes beyond the level. Confirmation costs you part of the move and saves you from a large share of the false ones. Studies of candlestick patterns show their edge is mostly in the confirmed versions.', related: ['fakeout', 'breakout', 'close'], lesson: '/learn/m02-candlestick-patterns/16-pattern-reliability' },
  { id: 'confirmation-bias', term: 'Confirmation Bias', short: 'Noticing only the evidence that agrees with the position you already hold.', long: 'Once you are long, bullish headlines feel insightful and bearish ones feel like noise. The practical fix is to write down, before entering, exactly what would prove you wrong. Reviewing losing trades honestly is the other half of the cure.', related: ['sunk-cost', 'trading-journal', 'recency-bias'], lesson: '/learn/m08-trading-psychology/04-cognitive-biases' },
  { id: 'consolidation', term: 'Consolidation', short: 'A quiet pause where price moves in a tight area after a bigger move.', long: 'Consolidation is the market catching its breath: volume drops, candle bodies shrink and ranges narrow. Because volatility tends to alternate, tight consolidations often precede sharp expansions. Flags, pennants and rectangles are all named shapes of consolidation.', related: ['range', 'squeeze', 'flag'], lesson: '/learn/m03-market-structure/05-ranges-and-consolidation' },
  { id: 'contango', term: 'Contango', short: 'When future-dated contracts cost more than the current price.', long: 'It is the normal state for storable commodities, because holding oil or grain costs money. Funds that roll futures forward in contango sell cheap and buy dear each month, which erodes returns. That drag is why some commodity ETFs lag the spot price badly over years.', related: ['backwardation', 'rollover', 'commodity'], lesson: '/learn/m11-derivatives-and-other-markets/04-futures' },
  { id: 'correlation', term: 'Correlation', short: 'How closely two instruments tend to move together.', long: 'Correlation runs from plus one, moving in lockstep, to minus one, moving exactly opposite. Two tech giants might correlate at 0.8, meaning a position in each is close to a double-size position in one. Ignoring correlation is how traders accidentally risk six percent while believing they risked one.', related: ['diversification', 'sector', 'risk-management'], lesson: '/learn/m07-risk-management/08-correlation-and-diversification' },
  { id: 'covered-call', term: 'Covered Call', short: 'Selling a call option against shares you already own to collect income.', long: 'You own 100 shares at 50 and sell a 55 call for $1, keeping $100 whatever happens. If the stock finishes above 55, your shares are sold at 55 and you miss the rest of the upside. It is a conservative strategy that trades future gains for present cash.', related: ['call-option', 'premium', 'theta'], lesson: '/learn/m11-derivatives-and-other-markets/03-basic-options-strategies' },
  { id: 'cpi', term: 'CPI', short: 'The consumer price index: the main monthly measure of inflation.', long: 'It tracks the cost of a basket of everyday goods and services compared with a year ago. Because it drives what central banks do next, a surprise of even a tenth of a percent can swing entire markets. Core CPI strips out food and energy to show the underlying trend.', related: ['inflation', 'interest-rate', 'fomc'], lesson: '/learn/m10-fundamentals-and-macro/05-economic-calendar' },
  { id: 'crossover', term: 'Crossover', short: 'When a faster line crosses above or below a slower one, used as a signal.', long: 'A 9 EMA crossing above a 21 EMA says short-term momentum has overtaken the medium term. Crossovers are simple and mechanical, which is their charm, but they whipsaw badly in ranges. Most traders use them as a filter for trend direction rather than as the entry itself.', related: ['golden-cross', 'death-cross', 'moving-average'], lesson: '/learn/m05-indicators/03-ma-crossovers' },
  { id: 'crypto', term: 'Crypto', short: 'Digital assets like Bitcoin that trade on their own exchanges every hour of the year.', long: 'Crypto markets never close, which sounds convenient and is actually exhausting: a position can move violently while you sleep. Liquidity and regulation vary enormously between exchanges, and the exchange itself is a risk, not just the asset. Treat position sizes here as smaller than you would for shares.', related: ['perpetual-futures', 'funding-rate', 'volatility'], lesson: '/learn/m11-derivatives-and-other-markets/06-crypto' },
  { id: 'cup-and-handle', term: 'Cup and Handle', short: 'A rounded bottom followed by a small pullback, then a breakout.', long: 'The cup is a slow U-shaped recovery back to an old high, taking weeks or months. The handle is a shallow drift lower that shakes out impatient holders before the breakout. A handle that retraces more than about a third of the cup is usually considered too deep.', related: ['breakout', 'measured-move', 'consolidation'], lesson: '/learn/m04-chart-patterns/08-cup-and-handle' },
  { id: 'currency-pair', term: 'Currency Pair', short: 'Two currencies quoted together, showing how much of one buys the other.', long: 'In EURUSD the euro is the base and the dollar is the quote, so 1.0850 means one euro costs 1.0850 dollars. Buying the pair means buying euros and selling dollars at the same time. Majors involving the dollar have the tightest spreads and the deepest liquidity.', related: ['forex', 'pip', 'lot-size'], lesson: '/learn/m11-derivatives-and-other-markets/05-forex' },
  { id: 'daily-loss-limit', term: 'Daily Loss Limit', short: 'A fixed amount of loss after which you stop trading for the day.', long: 'A common rule is three times your per-trade risk, so three full losses end the session. Its purpose is not maths but psychology: it switches you off before tilt turns a bad day into a disaster. Professional firms impose these limits precisely because willpower fails under stress.', related: ['tilt', 'revenge-trading', 'discipline'], lesson: '/learn/m07-risk-management/09-daily-loss-limits' },
  { id: 'dark-cloud-cover', term: 'Dark Cloud Cover', short: 'An up candle followed by a down candle closing below the halfway point.', long: 'The bearish mirror of the piercing line. Price opens above the previous high, which looks strong, and then sells off to close deep inside the green body. That failed breakout inside a single candle is what makes it a useful warning at highs.', related: ['piercing-line', 'engulfing', 'fakeout'], lesson: '/learn/m02-candlestick-patterns/08-piercing-dark-cloud' },
  { id: 'day-trading', term: 'Day Trading', short: 'Opening and closing all positions within the same session.', long: 'No overnight risk means no gap surprises, at the cost of needing to be present during market hours. Day traders usually work on one-minute to fifteen-minute charts and take a handful of trades a day. Some jurisdictions impose minimum account sizes on frequent day traders.', related: ['scalping', 'swing-trading', 'session'], lesson: '/learn/m09-strategies/01-trading-styles' },
  { id: 'death-cross', term: 'Death Cross', short: 'The 50-period average crossing below the 200-period average.', long: 'The bearish twin of the golden cross, and equally late. It has a dramatic name and a mediocre record as a standalone sell signal. Its real use is as a simple regime filter: below it, be more cautious with long trades.', related: ['golden-cross', 'crossover', 'bear-market'], lesson: '/learn/m05-indicators/03-ma-crossovers' },
  { id: 'delta', term: 'Delta', short: 'How much an option price moves for a one dollar move in the underlying.', long: 'A delta of 0.50 means the option gains about fifty cents when the stock gains a dollar. Delta is also a rough estimate of the chance of finishing in the money. Deep in the money options approach a delta of 1 and behave almost like the shares themselves.', related: ['gamma', 'theta', 'in-the-money'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'demand-zone', term: 'Demand Zone', short: 'An area where heavy buying previously appeared and may appear again.', long: 'The mirror of a supply zone: the tight base a rally exploded away from. Marked well, it gives you a place to look for entries with an obvious stop just below. Zones lose potency each time they are touched, because the resting orders get used up.', related: ['supply-zone', 'support', 'accumulation'], lesson: '/learn/m03-market-structure/08-supply-and-demand-zones' },
  { id: 'derivative', term: 'Derivative', short: 'A contract whose value comes from the price of something else.', long: 'Options, futures, CFDs and swaps are all derivatives: you never hold the underlying asset, only an agreement about it. They allow precise bets on direction, time and volatility, and they usually come with leverage built in. That leverage is why they are the fastest route to both profit and ruin.', related: ['options', 'futures', 'cfd'], lesson: '/learn/m11-derivatives-and-other-markets/01-options-basics' },
  { id: 'discipline', term: 'Discipline', short: 'Doing what your plan says even when your feelings disagree.', long: 'Discipline is not gritted teeth, it is good design: checklists, fixed sizes, alarms instead of staring at charts. Pilots do not rely on memory in a crisis and neither should traders. Judge yourself weekly on rule compliance, not on profit.', related: ['trading-plan', 'trading-journal', 'daily-loss-limit'], lesson: '/learn/m08-trading-psychology/07-routines-and-discipline' },
  { id: 'disposition-effect', term: 'Disposition Effect', short: 'The habit of selling winners too soon and holding losers too long.', long: 'It is loss aversion in action, and it shows up clearly in brokerage data across millions of accounts. The damage is structural: it caps your best trades and lets your worst ones run. Checking whether your average win is bigger than your average loss exposes it instantly.', related: ['loss-aversion', 'take-profit', 'r-multiple'], lesson: '/learn/m08-trading-psychology/04-cognitive-biases' },
  { id: 'distribution', term: 'Distribution', short: 'A quiet phase where large holders sell into strength without crashing the price.', long: 'After a long markup, price stalls and chops sideways near the highs while big positions are handed to enthusiastic latecomers. Volume stays high but progress stops, which is the tell. Distribution ends when support breaks and markdown begins.', related: ['accumulation', 'markdown', 'wyckoff'], lesson: '/learn/m03-market-structure/09-market-cycles-wyckoff' },
  { id: 'divergence', term: 'Divergence', short: 'When price makes a new extreme but the indicator does not agree.', long: 'Regular bearish divergence is a higher high in price paired with a lower high in RSI, hinting that momentum is fading. Hidden divergence points the other way and suggests continuation. Divergence can persist for a long time, so it is a warning to tighten risk rather than a reversal trade on its own.', related: ['rsi', 'macd', 'confirmation'], lesson: '/learn/m05-indicators/14-divergence' },
  { id: 'diversification', term: 'Diversification', short: 'Spreading risk across things that do not all move together.', long: 'Five different airline stocks are not diversification, they are one bet on aviation wearing five hats. Real diversification needs assets driven by different forces, and even those converge in a crisis. For a small trader, limiting total open risk is usually more practical than clever diversification.', related: ['correlation', 'sector', 'risk-management'], lesson: '/learn/m07-risk-management/08-correlation-and-diversification' },
  { id: 'doji', term: 'Doji', short: 'A candle whose open and close are almost identical, showing indecision.', long: 'A doji is a cross: barely any body, wicks on both sides. It says buyers and sellers fought all period and ended exactly where they started. On its own it means little, but a doji after a long run often warns that the trend has run out of fuel.', related: ['dragonfly-doji', 'gravestone-doji', 'spinning-top'], lesson: '/learn/m02-candlestick-patterns/02-doji-family' },
  { id: 'double-bottom', term: 'Double Bottom', short: 'Two failed attempts to break the same low, forming a W shape.', long: 'Sellers push to a level twice and cannot get through, which suggests buyers are absorbing everything offered. Confirmation comes from a close above the peak between the two lows. The second low being slightly higher than the first is generally seen as a healthier version.', related: ['double-top', 'support', 'confirmation'], lesson: '/learn/m04-chart-patterns/03-double-triple-tops-bottoms' },
  { id: 'double-top', term: 'Double Top', short: 'Two failed attempts at roughly the same high, forming an M shape.', long: 'Price rallies to a level, pulls back, rallies to the same level and fails again, showing sellers defending it. The trade triggers when price breaks the low between the two peaks. If a stock stalls at 120 twice and then loses the 112 middle low, the measured target is about 104.', related: ['double-bottom', 'resistance', 'measured-move'], lesson: '/learn/m04-chart-patterns/03-double-triple-tops-bottoms' },
  { id: 'downtrend', term: 'Downtrend', short: 'A sequence of lower highs and lower lows.', long: 'Every bounce fails below the previous bounce and every drop goes further than the last. It ends when price makes a high above the previous high, not when it simply feels oversold. Buying inside a downtrend because it looks cheap is one of the most expensive beginner habits.', related: ['uptrend', 'swing-low', 'markdown'], lesson: '/learn/m03-market-structure/01-trends' },
  { id: 'dragonfly-doji', term: 'Dragonfly Doji', short: 'A doji with a long lower wick and no upper wick, hinting at a bounce.', long: 'Price fell hard during the period and then climbed all the way back to the open. If the open and close are both at 100 and the low was 96, sellers gained four dollars and gave every cent back. Found at the bottom of a decline, it is a bullish clue that still needs confirmation.', related: ['doji', 'hammer', 'gravestone-doji'], lesson: '/learn/m02-candlestick-patterns/02-doji-family' },
  { id: 'drawdown', term: 'Drawdown', short: 'The drop from a peak in your account value to the lowest point after it.', long: 'If you grow $10,000 to $12,000 and fall back to $10,800, that is a 10% drawdown. Every strategy has them and they always feel longer than the spreadsheet suggests. Knowing the typical drawdown of your approach in advance is what stops you abandoning it at the worst moment.', related: ['max-drawdown', 'equity-curve', 'risk-of-ruin'], lesson: '/learn/m07-risk-management/07-drawdown-and-risk-of-ruin' },
  { id: 'earnings', term: 'Earnings', short: 'A company profit report, published every three months.', long: 'Earnings season moves individual stocks more than almost anything else, often by five or ten percent overnight. What matters is usually the surprise against expectations and the guidance, not the raw number. Holding a position through an earnings release is a gamble, not a trade.', related: ['eps', 'guidance', 'gap'], lesson: '/learn/m10-fundamentals-and-macro/02-earnings-and-financial-statements' },
  { id: 'edge', term: 'Edge', short: 'A repeatable reason why your trades make money over a large sample.', long: 'An edge can come from a pattern, a structural quirk, faster execution or simply better discipline than the average participant. It must be measurable, which means you can state the expectancy. Without an edge you are paying spreads for entertainment.', related: ['expectancy', 'backtesting', 'sample-size'], lesson: '/learn/m09-strategies/02-what-is-an-edge' },
  { id: 'ema', term: 'Exponential Moving Average', short: 'A moving average that weights recent prices more heavily than old ones.', long: 'The EMA reacts faster than the SMA because each new close gets a bigger share of the calculation. That makes it better for short-term work and worse for filtering noise. The 9 and 21 EMAs are staples for day traders, while the 200 EMA frames the long-term trend.', related: ['sma', 'moving-average', 'macd'], lesson: '/learn/m05-indicators/02-moving-averages' },
  { id: 'engulfing', term: 'Engulfing Pattern', short: 'A candle whose body completely swallows the previous candle body.', long: 'A bullish engulfing appears after a decline: a small red candle followed by a big green one that opens lower and closes above the previous open. It shows the balance flipping in a single period. The bigger the engulfing candle and the higher its volume, the more it matters.', related: ['harami', 'confirmation', 'body'], lesson: '/learn/m02-candlestick-patterns/06-engulfing' },
  { id: 'eps', term: 'EPS', short: 'Earnings per share: total profit divided by the number of shares.', long: 'A company earning $200 million with 100 million shares has an EPS of $2. It lets you compare profitability across companies of very different sizes. Watch for share buybacks, which raise EPS without the business earning a penny more.', related: ['earnings', 'pe-ratio', 'share'], lesson: '/learn/m10-fundamentals-and-macro/03-valuation-basics' },
  { id: 'equity-curve', term: 'Equity Curve', short: 'A chart of your account balance over time.', long: 'The shape matters more than the endpoint: a smooth climb suggests process, a jagged one suggests luck and oversizing. Plotting it in R rather than dollars removes the distortion from deposits and changing size. Many traders apply a moving average to their own curve as a warning system.', related: ['drawdown', 'sharpe-ratio', 'trading-journal'], lesson: '/learn/m12-becoming-consistent/02-performance-metrics' },
  { id: 'etf', term: 'ETF', short: 'A basket of many assets wrapped into one share you can trade like a stock.', long: 'An exchange traded fund holds a collection, such as the 500 companies of the S&P 500, and issues shares against it. Buying one share of SPY gives you a sliver of all 500 at once, which is instant diversification for the price of a single trade. ETFs charge a small annual fee called the expense ratio.', related: ['index', 'expense-ratio', 'diversification'], lesson: '/learn/m11-derivatives-and-other-markets/07-etfs-and-leveraged-products' },
  { id: 'evening-star', term: 'Evening Star', short: 'A three-candle top: big up candle, small pause, big down candle.', long: 'The mirror of the morning star, and one of the more statistically respected reversal patterns. The small middle candle shows buying losing steam right at the highs, and the third candle confirms by closing deep into the green body. Best taken at resistance rather than in the middle of a range.', related: ['morning-star', 'resistance', 'confirmation'], lesson: '/learn/m02-candlestick-patterns/10-morning-evening-star' },
  { id: 'exchange', term: 'Exchange', short: 'The official venue that matches buy and sell orders and publishes the prices.', long: 'Exchanges such as the NYSE, Nasdaq or the NSE keep the order book, match trades and make sure both sides actually deliver. They also set the trading hours and the rules. You almost never talk to an exchange directly, because your broker does it for you.', related: ['broker', 'market-maker', 'order-book'], lesson: '/learn/m00-what-is-a-market/05-the-players' },
  { id: 'expectancy', term: 'Expectancy', short: 'The average amount you expect to make per trade over many trades.', long: 'Expectancy equals win rate times average win, minus loss rate times average loss. A 40% win rate with 3R winners and 1R losers gives 0.4 times 3 minus 0.6 times 1, or plus 0.6R per trade. If this number is negative, no amount of discipline will save the strategy.', related: ['win-rate', 'r-multiple', 'profit-factor'], lesson: '/learn/m07-risk-management/05-expectancy' },
  { id: 'expense-ratio', term: 'Expense Ratio', short: 'The yearly percentage a fund charges for managing your money.', long: 'A 0.03% ratio costs $3 a year per $10,000, while a 1% ratio costs $100. It is deducted quietly from the fund value rather than billed to you. Over decades, a one percent difference can consume a large slice of total returns.', related: ['etf', 'leveraged-etf', 'commission'], lesson: '/learn/m11-derivatives-and-other-markets/07-etfs-and-leveraged-products' },
  { id: 'expiry', term: 'Expiry', short: 'The date an option or futures contract stops existing.', long: 'After expiry an option is either exercised or worthless, with no second chances. The closer expiry gets, the faster time value drains away, which punishes buyers and rewards sellers. Weekly options exist, and they decay brutally in the final days.', related: ['theta', 'extrinsic-value', 'rollover'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'extension', term: 'Fibonacci Extension', short: 'Levels projected beyond the previous high to estimate where a move may end.', long: 'The common targets are 1.272, 1.618 and 2.0 times the prior swing. If a move ran from 100 to 150 and pulled back to 125, the 1.618 extension sits near 206. Like all targets, they are planning tools, not predictions.', related: ['fibonacci', 'measured-move', 'take-profit'], lesson: '/learn/m05-indicators/12-fibonacci' },
  { id: 'extrinsic-value', term: 'Extrinsic Value', short: 'The part of an option premium that is time value rather than real profit.', long: 'If that 50 strike call with the stock at 56 costs $7.50, then $1.50 is extrinsic. It shrinks every day and vanishes completely at expiry, which is why option buyers fight a clock. Higher implied volatility inflates extrinsic value.', related: ['intrinsic-value', 'theta', 'implied-volatility'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'fakeout', term: 'Fakeout', short: 'A break of a level that immediately reverses and traps the traders who chased it.', long: 'Also called a false breakout or a bull trap. Price pushes through the level, triggers the stops resting beyond it, then snaps back inside the range. Fakeouts are so common that fading them is a strategy in its own right, especially at obvious round numbers.', related: ['breakout', 'confirmation', 'retest'], lesson: '/learn/m03-market-structure/06-breakouts-and-fakeouts' },
  { id: 'fear', term: 'Fear', short: 'The urge to avoid loss that makes traders cut winners early and freeze at entries.', long: 'Fear is useful when it enforces your stop and harmful when it closes a good trade at plus half an R. It usually shows up as hesitation before entry and impatience after it. The cure is not courage but a plan small enough that the outcome does not frighten you.', related: ['greed', 'loss-aversion', 'discipline'], lesson: '/learn/m08-trading-psychology/01-fear-and-greed' },
  { id: 'fibonacci', term: 'Fibonacci Levels', short: 'Ratios like 38.2%, 50% and 61.8% used to guess where a pullback might end.', long: 'You anchor the tool from a swing low to a swing high and read the levels in between. If a stock runs from 100 to 150, the 61.8% retracement sits near 119. The levels work mostly because a great many traders are watching the same numbers.', related: ['retracement', 'extension', 'pullback'], lesson: '/learn/m05-indicators/12-fibonacci' },
  { id: 'fill', term: 'Fill', short: 'The actual execution of your order, at the actual price you received.', long: 'The fill, not the price you clicked, is what appears in your account. Comparing the two over many trades tells you how much execution quality is costing you. Good traders track this the way a shop tracks shrinkage.', related: ['partial-fill', 'slippage', 'order'], lesson: '/learn/m06-orders-and-execution/07-slippage-and-liquidity' },
  { id: 'flag', term: 'Flag', short: 'A short, tilted pause after a sharp move, usually leading to a continuation.', long: 'The sharp move is the flagpole and the small drifting channel against it is the flag. Flags are brief, often five to fifteen candles, and volume should dry up inside them. The classic target adds the flagpole height to the breakout point.', related: ['pennant', 'measured-move', 'momentum'], lesson: '/learn/m04-chart-patterns/05-flags-and-pennants' },
  { id: 'fomc', term: 'FOMC', short: 'The US Federal Reserve committee that decides American interest rates.', long: 'It meets roughly eight times a year, and the announcement plus press conference regularly produce the largest candles of the month. Volatility often spikes in both directions within minutes as the statement is digested. Many traders simply stand aside for the first thirty minutes.', related: ['central-bank', 'interest-rate', 'volatility'], lesson: '/learn/m10-fundamentals-and-macro/05-economic-calendar' },
  { id: 'fomo', term: 'FOMO', short: 'Fear of missing out: chasing a move because everyone else seems to be profiting.', long: 'FOMO entries happen late, far from any sensible stop, which means large risk for small remaining upside. The tell is entering without being able to say where you are wrong. If you missed the move, the correct action is to wait for the next setup, not to buy this one higher.', related: ['greed', 'momentum', 'discipline'], lesson: '/learn/m08-trading-psychology/02-fomo-and-chasing' },
  { id: 'forex', term: 'Forex', short: 'The market where one currency is traded against another, open 24 hours a day.', long: 'Forex, short for foreign exchange, is the largest market in the world by turnover. You never buy a currency alone; you always buy one and sell another, which is why prices are quoted as pairs like EURUSD. It runs continuously from Sunday evening to Friday evening because some financial centre is always awake.', related: ['currency-pair', 'pip', 'lot-size'], lesson: '/learn/m11-derivatives-and-other-markets/05-forex' },
  { id: 'forward-testing', term: 'Forward Testing', short: 'Running your rules on live data going forward, without real money at first.', long: 'It removes the hindsight that quietly contaminates most backtests. Forward testing also reveals practical problems: missed signals, slow execution, setups that are hard to spot in real time. Thirty to fifty live trades is a reasonable minimum before risking meaningful money.', related: ['paper-trading', 'backtesting', 'sample-size'], lesson: '/learn/m09-strategies/09-backtesting-and-forward-testing' },
  { id: 'fundamental-analysis', term: 'Fundamental Analysis', short: 'Valuing something by studying the business or economy behind it.', long: 'It asks what a company earns, what it owns and what it is likely to earn next, then compares that to the price. Fundamentals explain why a move happens but are almost useless for timing it. Most traders use them to choose what to trade and technicals to decide when.', related: ['technical-analysis', 'earnings', 'pe-ratio'], lesson: '/learn/m10-fundamentals-and-macro/01-technical-vs-fundamental' },
  { id: 'funding-rate', term: 'Funding Rate', short: 'A periodic payment between long and short holders of perpetual futures.', long: 'When the perpetual trades above spot, longs pay shorts, which discourages excessive bullish positioning. Rates are usually charged every eight hours and are small, but they compound on leveraged positions. Extremely positive funding is often read as a sign of a crowded long trade.', related: ['perpetual-futures', 'crypto', 'sentiment'], lesson: '/learn/m11-derivatives-and-other-markets/06-crypto' },
  { id: 'futures', term: 'Futures', short: 'Contracts to buy or sell something at a set price on a set future date.', long: 'Futures started as a way for farmers and airlines to lock in prices months ahead, and traders joined in for the leverage and the round-the-clock hours. Each contract controls a fixed quantity, so one E-mini S&P contract represents fifty times the index value. They expire, which means you must roll or close before the date.', related: ['futures-contract', 'rollover', 'tick-value'], lesson: '/learn/m11-derivatives-and-other-markets/04-futures' },
  { id: 'futures-contract', term: 'Futures Contract', short: 'A standardised agreement to trade a fixed quantity on a fixed future date.', long: 'Everything is specified by the exchange: quantity, quality, delivery date and tick size. One E-mini S&P 500 contract represents fifty dollars times the index, so a ten point move is five hundred dollars. Margin is a performance deposit, not a down payment, which is why leverage here is high.', related: ['futures', 'tick-size', 'tick-value'], lesson: '/learn/m11-derivatives-and-other-markets/04-futures' },
  { id: 'gamma', term: 'Gamma', short: 'How quickly delta itself changes as the underlying moves.', long: 'High gamma means your exposure shifts fast, which is thrilling when right and alarming when wrong. Gamma is largest for options near the strike and close to expiry. It is the reason short-dated option positions can swing wildly within a single hour.', related: ['delta', 'theta', 'expiry'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'gap', term: 'Gap', short: 'A jump between one candle closing and the next one opening at a different price.', long: 'Gaps happen when news arrives while the market is shut, so the first trade of the new session is far from the last one. A stock closing at 50 and opening at 56 has gapped up six dollars, and anyone holding a stop at 49 will have been skipped entirely. Some gaps get filled quickly, others never do.', related: ['pre-market', 'window', 'earnings'], lesson: '/learn/m01-reading-price/07-gaps' },
  { id: 'gdp', term: 'GDP', short: 'The total value of everything a country produces, the broadest growth measure.', long: 'It is reported quarterly and revised, which makes it slow news compared with jobs or inflation data. Two consecutive quarters of shrinking GDP is the common rough definition of a recession. Markets care most about how the figure compares to the forecast.', related: ['inflation', 'nfp', 'central-bank'], lesson: '/learn/m10-fundamentals-and-macro/05-economic-calendar' },
  { id: 'golden-cross', term: 'Golden Cross', short: 'The 50-period average crossing above the 200-period average.', long: 'It is a slow, famous signal that a long-term uptrend may be starting, and it always arrives well after the low. Because so many people watch it on the daily chart, it generates headlines and sometimes flows. Treat it as weather, not as an entry trigger.', related: ['death-cross', 'crossover', 'sma'], lesson: '/learn/m05-indicators/03-ma-crossovers' },
  { id: 'gravestone-doji', term: 'Gravestone Doji', short: 'A doji with a long upper wick and no lower wick, hinting at a top.', long: 'Buyers pushed price up all period and then lost every bit of it by the close. It is the mirror image of the dragonfly, and it is most meaningful at the top of a rally or at a known resistance level. Like all doji, it is a warning, not an order to sell.', related: ['doji', 'shooting-star', 'dragonfly-doji'], lesson: '/learn/m02-candlestick-patterns/02-doji-family' },
  { id: 'greed', term: 'Greed', short: 'The urge for more that makes traders oversize, overstay and overtrade.', long: 'Greed rarely announces itself; it arrives as a good reason to take a slightly bigger position this once. It is most dangerous after a winning streak, when confidence is highest and caution lowest. Fixed rules on size and targets are what keep it in a box.', related: ['fear', 'fomo', 'overtrading'], lesson: '/learn/m08-trading-psychology/01-fear-and-greed' },
  { id: 'gtc', term: 'GTC', short: 'Good Til Cancelled: an order that stays active until it fills or you remove it.', long: 'Useful for limit orders at levels you expect price to reach in a few weeks. Dangerous because markets change and you forget: a GTC buy at 40 placed before bad news can fill into a collapse. Review your resting orders as part of your weekly routine.', related: ['time-in-force', 'limit-order', 'order'], lesson: '/learn/m06-orders-and-execution/04-time-in-force' },
  { id: 'guidance', term: 'Guidance', short: "A company's own forecast of its coming results.", long: 'Guidance often moves the share price more than the results just reported, because markets price the future. A company can beat expectations and still fall ten percent if it lowers guidance. Withdrawn guidance is usually a red flag about visibility.', related: ['earnings', 'catalyst', 'gap'], lesson: '/learn/m10-fundamentals-and-macro/08-news-catalysts-and-events' },
  { id: 'hammer', term: 'Hammer', short: 'A small body at the top with a long lower wick, appearing after a fall.', long: 'The long lower wick should be at least twice the body. It shows sellers drove price down and were completely overpowered before the close. A hammer at support with rising volume is one of the more trustworthy single-candle signals, but you still wait for the next candle to confirm.', related: ['hanging-man', 'inverted-hammer', 'support'], lesson: '/learn/m02-candlestick-patterns/03-hammer-hanging-man' },
  { id: 'hanging-man', term: 'Hanging Man', short: 'The same shape as a hammer, but appearing after a rise, warning of a top.', long: 'Shape alone never tells you the meaning; location does. The long lower wick after an extended rally shows that selling pressure has appeared for the first time in a while. Traders usually want the following candle to close lower before acting on it.', related: ['hammer', 'shooting-star', 'resistance'], lesson: '/learn/m02-candlestick-patterns/03-hammer-hanging-man' },
  { id: 'harami', term: 'Harami', short: 'A small candle contained inside the previous large candle body.', long: 'Harami means pregnant in Japanese, and the picture is exactly that: a big candle with a little one inside it. It signals that momentum has stalled rather than reversed. If the inner candle is a doji it is called a harami cross and is considered a stronger warning.', related: ['engulfing', 'doji', 'consolidation'], lesson: '/learn/m02-candlestick-patterns/07-harami-and-harami-cross' },
  { id: 'head-and-shoulders', term: 'Head and Shoulders', short: 'A three-peak topping pattern with a higher middle peak and a neckline below.', long: 'The left shoulder, the higher head and the lower right shoulder show buyers failing to make new highs. The pattern only counts once price closes below the neckline joining the two troughs. The inverse version, upside down, marks bottoms in exactly the same way.', related: ['neckline', 'measured-move', 'double-top'], lesson: '/learn/m04-chart-patterns/02-head-and-shoulders' },
  { id: 'high', term: 'High', short: 'The highest price reached during a candle or session.', long: 'The high is the top of the upper wick and marks the furthest buyers could push before sellers stopped them. Yesterday high and the session high often become short term resistance because traders remember them. Strings of higher highs are the signature of an uptrend.', related: ['low', 'wick', 'higher-high'], lesson: '/learn/m01-reading-price/03-anatomy-of-a-candle' },
  { id: 'higher-high', term: 'Higher High', short: 'A peak that rises above the previous peak.', long: 'Higher highs show that buyers are willing to pay more than they were last time. One higher high is not a trend; a sequence of them, paired with higher lows, is. When a rally fails to exceed the previous high, the uptrend is showing its first crack.', related: ['higher-low', 'uptrend', 'swing-high'], lesson: '/learn/m03-market-structure/01-trends' },
  { id: 'higher-low', term: 'Higher Low', short: 'A pullback that stops above the previous pullback low.', long: 'Higher lows are the more important half of an uptrend, because they show sellers running out of room. They are also where pullback traders look to enter, with a stop just under the low. The moment a higher low fails, the trend structure is broken.', related: ['higher-high', 'uptrend', 'pullback'], lesson: '/learn/m03-market-structure/01-trends' },
  { id: 'ichimoku', term: 'Ichimoku Cloud', short: 'A Japanese system showing trend, support and momentum in one shaded picture.', long: 'It combines five lines, the most visible being the cloud drawn ahead of price. Price above the cloud is bullish, below is bearish, and inside is undecided. It looks intimidating but its core message is simply trend plus distance from fair value.', related: ['overlay', 'trend', 'moving-average'], lesson: '/learn/m05-indicators/13-pivot-points-and-ichimoku' },
  { id: 'implied-volatility', term: 'Implied Volatility', short: 'The amount of future movement that option prices are currently predicting.', long: 'It is derived backwards from the price people are paying, so it measures expectation rather than history. High implied volatility means expensive options and a market bracing for something. Comparing it to actual past volatility tells you whether options are cheap or dear.', related: ['vega', 'iv-crush', 'vix'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'in-the-money', term: 'In the Money', short: 'An option that already has real value if exercised today.', long: 'A call is in the money when price is above the strike; a put when price is below it. In the money options cost more, move more like the underlying, and carry less time value as a proportion. They are the conservative choice for directional bets.', related: ['out-of-the-money', 'intrinsic-value', 'delta'], lesson: '/learn/m11-derivatives-and-other-markets/01-options-basics' },
  { id: 'index', term: 'Index', short: 'A number that tracks a group of stocks, used as a scoreboard for a market.', long: 'The S&P 500, FTSE 100 and Nifty 50 are indices: recipes that combine many companies into one figure. You cannot buy an index directly, but you can buy an ETF or a futures contract that follows it. When people say the market is up, they almost always mean an index.', related: ['etf', 'market-cap', 'sector'], lesson: '/learn/m00-what-is-a-market/06-what-can-you-trade' },
  { id: 'indicator', term: 'Indicator', short: 'A calculation applied to price or volume, drawn to make a pattern easier to see.', long: 'Every indicator is arithmetic on data you already have, so none of them contain secret information. They compress history into one line, which helps your eyes and costs you detail. The skill is choosing two or three that answer different questions rather than ten that agree with each other.', related: ['oscillator', 'overlay', 'lagging-indicator'], lesson: '/learn/m05-indicators/01-what-indicators-are' },
  { id: 'inflation', term: 'Inflation', short: 'The rate at which prices rise and money loses purchasing power.', long: 'At three percent inflation, $100 buys what $97 bought a year ago. Moderate inflation is normal; rapid inflation forces central banks to raise rates, which pressures share prices. It is the single macro variable that most reliably sets the mood of every market.', related: ['cpi', 'interest-rate', 'central-bank'], lesson: '/learn/m10-fundamentals-and-macro/04-interest-rates-and-central-banks' },
  { id: 'interest-rate', term: 'Interest Rate', short: 'The price of borrowing money, set at the base level by central banks.', long: 'Higher rates make borrowing expensive, slow the economy and make safe savings more attractive than shares. That is why rate expectations move every market at once, from bonds to gold to tech stocks. Traders watch not the current rate but the expected path of future rates.', related: ['central-bank', 'fomc', 'yield'], lesson: '/learn/m10-fundamentals-and-macro/04-interest-rates-and-central-banks' },
  { id: 'intrinsic-value', term: 'Intrinsic Value', short: 'The part of an option premium that would be profit if exercised right now.', long: 'A 50 strike call with the stock at 56 has $6 of intrinsic value. Out of the money options have zero intrinsic value: they are pure time and hope. At expiry, intrinsic value is all that remains.', related: ['extrinsic-value', 'in-the-money', 'premium'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'inverted-hammer', term: 'Inverted Hammer', short: 'A small body at the bottom with a long upper wick, appearing after a fall.', long: 'Buyers tried to lift price and did not quite hold it, yet the attempt itself is news after a long decline. It is a weaker signal than the hammer and almost always needs a strong up candle after it. Same shape as a shooting star, opposite location.', related: ['hammer', 'shooting-star', 'confirmation'], lesson: '/learn/m02-candlestick-patterns/04-shooting-star-inverted-hammer' },
  { id: 'iv-crush', term: 'IV Crush', short: 'The sudden collapse in option prices right after an expected event passes.', long: 'Before earnings, uncertainty inflates implied volatility and therefore premiums. The moment results are out, that uncertainty disappears and premium deflates, sometimes by half. Traders who buy options for an earnings move often lose even when the stock moves their way.', related: ['implied-volatility', 'vega', 'earnings'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'lagging-indicator', term: 'Lagging Indicator', short: 'A tool that confirms a move after it has already begun.', long: 'Moving averages are the obvious example: a 200-day average cannot turn until months of data have shifted. Lag is the price you pay for filtering out noise, and it is often worth paying. Problems start when traders expect a lagging tool to call a top.', related: ['leading-indicator', 'moving-average', 'crossover'], lesson: '/learn/m05-indicators/01-what-indicators-are' },
  { id: 'leading-indicator', term: 'Leading Indicator', short: 'A tool that tries to hint at a turn before it happens.', long: 'Oscillators such as RSI and stochastic are usually put in this camp because they can diverge from price before it reverses. The trade-off is more false alarms, especially in strong trends. In practice most traders pair a leading signal with a lagging filter.', related: ['lagging-indicator', 'divergence', 'oscillator'], lesson: '/learn/m05-indicators/01-what-indicators-are' },
  { id: 'level-2', term: 'Level 2', short: 'A data feed showing the depth of the order book beyond the best prices.', long: 'Level 1 gives you the best bid and ask; Level 2 shows several price levels and who is quoting them. It is most useful to scalpers working in seconds, and mostly a distraction for swing traders. Displayed size can vanish the instant you try to trade against it.', related: ['order-book', 'liquidity', 'scalping'], lesson: '/learn/m06-orders-and-execution/08-order-book-and-level-2' },
  { id: 'leverage', term: 'Leverage', short: 'Controlling a position larger than your account through borrowing.', long: 'Ten to one leverage means $1,000 controls $10,000 of exposure, so a one percent adverse move costs ten percent of your capital. Leverage does not change the quality of a trade, only the speed at which the outcome arrives. The professional use of it is to keep risk constant, not to raise it.', related: ['margin', 'margin-call', 'position-sizing'], lesson: '/learn/m06-orders-and-execution/06-margin-and-leverage' },
  { id: 'leveraged-etf', term: 'Leveraged ETF', short: 'A fund that aims to deliver two or three times the daily move of an index.', long: 'The key word is daily: it resets every day, so returns compound in strange ways over longer periods. An index that falls ten percent and then rises eleven percent is roughly flat, while a 3x fund on it is meaningfully down. They are tools for days, not for holding.', related: ['etf', 'leverage', 'expense-ratio'], lesson: '/learn/m11-derivatives-and-other-markets/07-etfs-and-leveraged-products' },
  { id: 'limit-order', term: 'Limit Order', short: 'An order to trade only at your chosen price or better.', long: 'A buy limit at 49.50 will never pay more than 49.50, and may never fill at all if price runs away. You trade certainty of execution for certainty of price. Limit orders also add liquidity to the book, which some venues reward with lower fees.', related: ['market-order', 'order-book', 'fill'], lesson: '/learn/m06-orders-and-execution/01-market-and-limit-orders' },
  { id: 'liquidation', term: 'Liquidation', short: 'The broker or exchange force-closing your position to stop further losses.', long: 'In crypto and futures this is automatic and instant once your margin runs out. There is no negotiation and often no good price. Sizing so that liquidation is mathematically unreachable is the simplest protection available.', related: ['margin-call', 'leverage', 'risk-of-ruin'], lesson: '/learn/m06-orders-and-execution/06-margin-and-leverage' },
  { id: 'liquidity', term: 'Liquidity', short: 'How easily you can buy or sell without moving the price against yourself.', long: 'A liquid market has many buyers and sellers at every price, so a large order barely nudges the chart. A thin market has gaps in the order book, and the same order can jump the price several percent. Liquidity is why big traders stick to famous names and why tiny stocks can trap you.', related: ['slippage', 'volume', 'spread'], lesson: '/learn/m06-orders-and-execution/07-slippage-and-liquidity' },
  { id: 'log-scale', term: 'Logarithmic Scale', short: 'A price axis where equal distances mean equal percentage moves, not equal dollars.', long: 'On a linear chart, a move from 10 to 20 looks much smaller than a move from 100 to 110, even though the first doubled your money. A log scale fixes this by spacing by percentage. Use log for long multi-year charts and linear for intraday work.', related: ['timeframe', 'trendline', 'measured-move'], lesson: '/learn/m01-reading-price/08-log-vs-linear' },
  { id: 'long', term: 'Long', short: 'Owning an instrument, so you profit when the price rises.', long: 'Going long is the intuitive direction: buy at 50, sell at 60, keep the ten. Your maximum loss is what you paid, and your upside is theoretically unlimited. Most beginners should stay long-only until position sizing has become automatic.', related: ['short', 'position-sizing', 'order'], lesson: '/learn/m06-orders-and-execution/05-going-long-and-short' },
  { id: 'loss-aversion', term: 'Loss Aversion', short: 'The bias that makes losing $100 hurt about twice as much as gaining $100 pleases.', long: 'Because losses hurt more, traders close winners quickly to lock in relief and hold losers hoping to avoid the pain. That produces the exact opposite of a profitable distribution: small wins and large losses. Pre-set stops and targets exist to make this decision before the feeling arrives.', related: ['disposition-effect', 'fear', 'stop-loss'], lesson: '/learn/m08-trading-psychology/04-cognitive-biases' },
  { id: 'lot', term: 'Lot', short: 'A standard bundle size used when quoting or trading an instrument.', long: 'Markets count in different units: shares for stocks, lots for forex, contracts for futures. A round lot of shares is traditionally one hundred, while a standard forex lot is 100,000 units of the base currency. Knowing your unit is the difference between a sensible position and an accidental one ten times too big.', related: ['lot-size', 'share', 'position-sizing'], lesson: '/learn/m00-what-is-a-market/09-tickers-lots-and-units' },
  { id: 'lot-size', term: 'Lot Size', short: 'The quantity of currency units a forex trade controls.', long: 'A standard lot is 100,000 units, a mini lot 10,000 and a micro lot 1,000. Micro lots let a small account risk sensible amounts, roughly ten cents per pip. Choosing the lot size is how forex traders do position sizing.', related: ['pip', 'position-sizing', 'lot'], lesson: '/learn/m11-derivatives-and-other-markets/05-forex' },
  { id: 'low', term: 'Low', short: 'The lowest price reached during a candle or session.', long: 'The low is the bottom of the lower wick and shows how far sellers managed to drive price before buyers stepped in. Prior lows are natural places to put a stop loss, which is also why price sometimes dips just below them. Strings of higher lows are the other half of an uptrend definition.', related: ['high', 'wick', 'higher-low'], lesson: '/learn/m01-reading-price/03-anatomy-of-a-candle' },
  { id: 'macd', term: 'MACD', short: 'A momentum tool built from the gap between two moving averages.', long: 'The standard setup subtracts a 26 EMA from a 12 EMA, then plots a 9 EMA of that line as the signal. The histogram is the difference between those two and shows momentum speeding up or slowing down. It is a trend-following tool wearing an oscillator costume, so it lags at turns.', related: ['ema', 'crossover', 'divergence'], lesson: '/learn/m05-indicators/05-macd' },
  { id: 'margin', term: 'Margin', short: 'Money borrowed from your broker so you can hold a bigger position.', long: 'You put up a deposit and the broker funds the rest, charging interest. Margin magnifies both outcomes: with two to one margin, a five percent move becomes a ten percent change in your money. It also introduces a risk that does not exist otherwise, which is being closed out by the broker.', related: ['leverage', 'margin-call', 'liquidation'], lesson: '/learn/m06-orders-and-execution/06-margin-and-leverage' },
  { id: 'margin-call', term: 'Margin Call', short: 'A demand from your broker for more money because losses ate your deposit.', long: 'When equity falls below the maintenance requirement, you must add funds or reduce the position, usually within hours. Ignore it and the broker sells for you, at whatever price is available. Margin calls arrive exactly when markets are at their worst, which is why they hurt twice.', related: ['margin', 'liquidation', 'drawdown'], lesson: '/learn/m06-orders-and-execution/06-margin-and-leverage' },
  { id: 'markdown', term: 'Markdown', short: 'The falling phase of a cycle, when the decline becomes obvious to everyone.', long: 'Lower highs and lower lows, bad headlines and sharp bear rallies that fail. Markdown is usually faster than markup because fear moves quicker than optimism. It ends when selling exhausts itself and a new accumulation phase quietly begins.', related: ['distribution', 'downtrend', 'bear-market'], lesson: '/learn/m03-market-structure/09-market-cycles-wyckoff' },
  { id: 'market', term: 'Market', short: 'Any place where buyers and sellers meet and agree on a price.', long: 'A market does not have to be a building. It is simply the meeting point of everyone who wants to buy and everyone who wants to sell. A lemonade stand on a street corner is a market with two participants; the stock market is the same idea with millions.', related: ['exchange', 'broker', 'liquidity'], lesson: '/learn/m00-what-is-a-market/01-the-lemonade-stand' },
  { id: 'market-cap', term: 'Market Capitalisation', short: 'The total value of a company: share price multiplied by number of shares.', long: 'A company with 50 million shares at $20 each has a market cap of one billion dollars. Cap size tells you roughly what to expect: mega caps move slowly and trade tightly, micro caps move wildly and can be manipulated. Price per share alone tells you almost nothing about how big a company is.', related: ['share', 'pe-ratio', 'index'], lesson: '/learn/m10-fundamentals-and-macro/03-valuation-basics' },
  { id: 'market-maker', term: 'Market Maker', short: 'A firm that always quotes a buy and a sell price so others can trade instantly.', long: "A market maker earns the spread: it buys at the bid, sells at the ask, and pockets the difference. If the bid is 100.00 and the ask is 100.02, it makes two cents per share for standing in the middle. In return, you get to trade the moment you want to rather than waiting for a matching human.", related: ['bid', 'ask', 'liquidity'], lesson: '/learn/m00-what-is-a-market/05-the-players' },
  { id: 'market-order', term: 'Market Order', short: 'An order to trade immediately at whatever price is currently available.', long: 'You are guaranteed to be filled but not at any particular price. In a liquid stock that hardly matters; in a thin one, or during news, a market order can fill several percent away from what you saw. Use it when being in the trade matters more than the last few cents.', related: ['limit-order', 'slippage', 'ask'], lesson: '/learn/m06-orders-and-execution/01-market-and-limit-orders' },
  { id: 'markup', term: 'Markup', short: 'The rising phase of a cycle, when the trend is obvious and buyers pile in.', long: 'Markup is the part everybody recognises: higher highs, higher lows, news turning positive. Trend following strategies make most of their money here and almost none anywhere else. It ends not with a bang but with a stall into distribution.', related: ['accumulation', 'uptrend', 'trend-following'], lesson: '/learn/m03-market-structure/09-market-cycles-wyckoff' },
  { id: 'martingale', term: 'Martingale', short: 'Doubling your size after each loss in the hope of recovering everything at once.', long: 'The system comes from casino betting and guarantees eventual ruin with a finite account. After six losses you need 64 times the original stake to break even. Any strategy that needs an unlimited bankroll to work is a strategy that ends at zero.', related: ['averaging-down', 'risk-of-ruin', 'revenge-trading'], lesson: '/learn/m07-risk-management/10-never-average-down' },
  { id: 'marubozu', term: 'Marubozu', short: 'A candle that is all body and no wicks, showing total one-sided control.', long: 'The open is the low and the close is the high, or exactly the reverse. It means one side pushed from the first tick to the last without ever being pushed back. Marubozu candles often start strong moves and their extremes make natural stop levels.', related: ['body', 'spinning-top', 'momentum'], lesson: '/learn/m02-candlestick-patterns/05-marubozu-spinning-top' },
  { id: 'max-drawdown', term: 'Maximum Drawdown', short: 'The worst peak-to-trough fall your account has ever suffered.', long: 'It is the headline risk number professionals look at first, because it describes the pain you must be able to sit through. A strategy returning 30% a year with a 50% maximum drawdown is unusable for most people. Assume your future worst is larger than your historical worst.', related: ['drawdown', 'sharpe-ratio', 'equity-curve'], lesson: '/learn/m12-becoming-consistent/02-performance-metrics' },
  { id: 'mean-reversion', term: 'Mean Reversion', short: 'Betting that a stretched price will snap back towards its average.', long: 'The opposite philosophy to trend following: buy the dip, sell the spike, expect the rubber band to pull back. Win rates are high but losses can be large, because the strategy is short volatility by nature. It works in ranges and gets destroyed in strong trends.', related: ['range', 'oversold', 'trend-following'], lesson: '/learn/m09-strategies/06-mean-reversion' },
  { id: 'measured-move', term: 'Measured Move', short: 'Turning a pattern height into a price target by projecting it from the break.', long: 'If a rectangle is eight dollars tall and breaks upward at 60, the measured target is 68. It is a rule of thumb from crowd behaviour, not a law, so treat it as a place to start taking profit rather than a promise. Always check whether the target sits beyond an obvious resistance level.', related: ['take-profit', 'rectangle', 'head-and-shoulders'], lesson: '/learn/m04-chart-patterns/09-measured-moves-and-targets' },
  { id: 'momentum', term: 'Momentum', short: 'The tendency of a strongly moving price to keep moving a while longer.', long: 'Momentum traders buy things that are already going up, which feels wrong and has been profitable across markets for decades. The risk is that momentum reverses violently and without warning. Position size and a hard stop matter more here than in slower styles.', related: ['trend-following', 'catalyst', 'fomo'], lesson: '/learn/m09-strategies/07-momentum-and-news' },
  { id: 'morning-star', term: 'Morning Star', short: 'A three-candle bottom: big down candle, small pause, big up candle.', long: 'The middle candle is a small body or doji that shows selling exhaustion, and the third candle should close well inside the first red body. It is named for the dawn because it marks the end of the dark stretch. Volume rising on the third candle makes it far more believable.', related: ['evening-star', 'doji', 'confirmation'], lesson: '/learn/m02-candlestick-patterns/10-morning-evening-star' },
  { id: 'moving-average', term: 'Moving Average', short: 'A smoothed line of average price that shows trend direction at a glance.', long: 'The direction of the line answers which way the market is leaning, and its slope answers how strongly. Price above a rising average is the simplest possible definition of an uptrend. They are useless in choppy markets, where price crosses them constantly.', related: ['sma', 'ema', 'crossover'], lesson: '/learn/m05-indicators/02-moving-averages' },
  { id: 'multi-timeframe', term: 'Multi-Timeframe Analysis', short: 'Checking a higher timeframe for direction and a lower one for entry timing.', long: 'A common pairing is the daily chart for trend and the one-hour chart for entries, roughly a four to six times zoom. It stops you from shorting into a powerful daily uptrend because a five-minute candle looked weak. The rule of thumb is to take trades in the direction of the larger picture.', related: ['timeframe', 'trend', 'pullback'], lesson: '/learn/m03-market-structure/10-multi-timeframe' },
  { id: 'neckline', term: 'Neckline', short: 'The line joining the lows of a head and shoulders pattern, used as the trigger.', long: 'Until price closes through the neckline, the pattern is only a drawing. The distance from the head down to the neckline is the classic target, projected from the break. Necklines are not always horizontal, and a sloping one is usually a weaker signal.', related: ['head-and-shoulders', 'measured-move', 'breakout'], lesson: '/learn/m04-chart-patterns/02-head-and-shoulders' },
  { id: 'nfp', term: 'Non-Farm Payrolls', short: 'The monthly US jobs report, released on the first Friday of the month.', long: 'It counts how many jobs the American economy added outside farming, and it is one of the biggest scheduled movers in forex. Currency pairs can travel a hundred pips in seconds on the release. Spreads widen sharply around it, so slippage is a real cost.', related: ['gdp', 'cpi', 'volatility'], lesson: '/learn/m10-fundamentals-and-macro/05-economic-calendar' },
  { id: 'obv', term: 'On-Balance Volume', short: 'A running total that adds volume on up days and subtracts it on down days.', long: 'The absolute number is meaningless; the direction of the line is the point. If price drifts sideways while OBV climbs, someone is accumulating quietly. OBV diverging from price is one of the cleaner volume-based warnings.', related: ['volume', 'volume-profile', 'divergence'], lesson: '/learn/m05-indicators/10-volume-indicators' },
  { id: 'oco', term: 'OCO Order', short: 'Two linked orders where filling one automatically cancels the other.', long: 'One Cancels the Other prevents the nightmare of both your stop and your target filling and leaving you accidentally short. It is the plumbing behind every bracket order. Any exit plan with two possible endings should be sent as an OCO.', related: ['bracket-order', 'take-profit', 'stop-loss'], lesson: '/learn/m06-orders-and-execution/03-bracket-and-oco' },
  { id: 'one-percent-rule', term: 'The 1% Rule', short: 'Never risk more than one percent of your account on a single trade.', long: 'On a $20,000 account that is $200 of risk per trade, no matter how good the setup looks. At one percent, ten losses in a row costs about ten percent, which is survivable and recoverable. Beginners often start at half a percent, which is even better.', related: ['position-sizing', 'risk-of-ruin', 'daily-loss-limit'], lesson: '/learn/m07-risk-management/02-the-one-percent-rule' },
  { id: 'open', term: 'Open', short: 'The first traded price of a candle or a session.', long: 'The open is where the period started, and on a daily chart it often reflects overnight news rather than yesterday evening. Comparing open to close tells you who won the period: close above open is bullish, below is bearish. The opening print of the day is one of the most watched prices on the chart.', related: ['close', 'candlestick', 'gap'], lesson: '/learn/m01-reading-price/03-anatomy-of-a-candle' },
  { id: 'options', term: 'Options', short: 'Contracts giving the right, but not the duty, to buy or sell at a fixed price.', long: 'An option buyer pays a premium for optionality and can lose only that premium. An option seller collects the premium and takes on the obligation, which can be far more expensive. Options let you shape a position around time and volatility, not just direction, which is powerful and easy to misuse.', related: ['call-option', 'put-option', 'premium'], lesson: '/learn/m11-derivatives-and-other-markets/01-options-basics' },
  { id: 'order', term: 'Order', short: 'An instruction to your broker to buy or sell an instrument.', long: 'An order specifies what, how much, in which direction and under what price conditions. Choosing the right type is how you control the trade-off between certainty of getting filled and certainty of the price. Everything else in execution is a variation on this one idea.', related: ['market-order', 'limit-order', 'time-in-force'], lesson: '/learn/m06-orders-and-execution/01-market-and-limit-orders' },
  { id: 'order-book', term: 'Order Book', short: 'The live list of all resting buy and sell orders at each price.', long: 'Bids stack below the current price and asks stack above, with the quantity waiting at each level. It shows where liquidity sits, though large players hide their true size. Reading it well helps with execution; reading too much into it invites being fooled by fake orders.', related: ['level-2', 'bid', 'ask'], lesson: '/learn/m06-orders-and-execution/08-order-book-and-level-2' },
  { id: 'oscillator', term: 'Oscillator', short: 'An indicator drawn in a separate panel that swings between fixed limits.', long: 'RSI and stochastic run from 0 to 100, MACD swings around zero. Because they are bounded they are good at showing momentum and extremes, and bad at showing how far a trend can run. An oscillator pinned at an extreme in a strong trend is describing strength, not a reversal.', related: ['rsi', 'stochastic', 'overbought'], lesson: '/learn/m05-indicators/01-what-indicators-are' },
  { id: 'out-of-the-money', term: 'Out of the Money', short: 'An option with no value if exercised today, only hope and time.', long: 'Cheap, exciting and usually worthless: most out of the money options expire at zero. They can multiply many times over when a large move happens, which is why lottery-ticket buying is so common. Sizing them as a total loss is the only sane approach.', related: ['in-the-money', 'extrinsic-value', 'premium'], lesson: '/learn/m11-derivatives-and-other-markets/01-options-basics' },
  { id: 'overbought', term: 'Overbought', short: 'An indicator reading that says price has risen quickly relative to recent history.', long: 'RSI above 70 is the classic example. It means stretched, not doomed, and in a powerful trend it can stay there for weeks while price keeps climbing. Selling purely because something is overbought is one of the most reliable ways to lose money in a bull market.', related: ['oversold', 'rsi', 'stochastic'], lesson: '/learn/m05-indicators/04-rsi' },
  { id: 'overfitting', term: 'Overfitting', short: 'Tuning a strategy so precisely to past data that it fails on new data.', long: 'Add enough filters and any set of rules can be made to look perfect on history. The warning signs are many parameters, oddly specific values, and results that collapse when a setting moves slightly. Simpler strategies with fewer knobs survive contact with the future more often.', related: ['backtesting', 'walk-forward', 'sample-size'], lesson: '/learn/m09-strategies/09-backtesting-and-forward-testing' },
  { id: 'overlay', term: 'Overlay', short: 'An indicator drawn on top of the price chart itself.', long: 'Moving averages, Bollinger Bands, VWAP and pivot points are overlays because they share the price axis. They are useful for levels and trend direction. Keeping more than two or three on a chart quickly turns it into spaghetti.', related: ['oscillator', 'moving-average', 'bollinger-bands'], lesson: '/learn/m05-indicators/01-what-indicators-are' },
  { id: 'oversold', term: 'Oversold', short: 'An indicator reading that says price has fallen quickly relative to recent history.', long: 'RSI below 30 is the usual threshold. In a range it often marks a good place to look for a bounce; in a downtrend it simply describes strength of selling. Always ask what the structure says before treating oversold as a buy signal.', related: ['overbought', 'rsi', 'mean-reversion'], lesson: '/learn/m05-indicators/04-rsi' },
  { id: 'overtrading', term: 'Overtrading', short: 'Taking far more trades than your strategy actually calls for.', long: 'It comes from boredom, from wanting action, or from believing that effort should equal activity. Each extra trade adds spread, commission and a fresh chance to make a mistake. Counting your trades each week and comparing them to your rules usually reveals the problem.', related: ['discipline', 'setup', 'commission'], lesson: '/learn/m08-trading-psychology/05-overtrading-and-boredom' },
  { id: 'paper-trading', term: 'Paper Trading', short: 'Practising with simulated money in real market conditions.', long: 'It is the safest way to learn the mechanics of your platform and to prove a plan can be followed. The limitation is emotional: losing fake money teaches you nothing about handling a real losing streak. Use it to validate process, then move to tiny real positions.', related: ['forward-testing', 'trading-plan', 'discipline'], lesson: '/learn/m12-becoming-consistent/07-from-simulator-to-real' },
  { id: 'partial-fill', term: 'Partial Fill', short: 'Only part of your order executes because not enough size was available.', long: 'Ask for 5,000 shares when only 1,200 are offered at your price and you get 1,200, with the rest resting or cancelled. It is common in thin instruments and at the edges of the order book. Always check the filled quantity before assuming your position size is what you intended.', related: ['fill', 'liquidity', 'order-book'], lesson: '/learn/m06-orders-and-execution/07-slippage-and-liquidity' },
  { id: 'pe-ratio', term: 'P/E Ratio', short: 'Share price divided by earnings per share: what you pay for each dollar of profit.', long: 'A stock at $40 with EPS of $2 has a P/E of 20, meaning twenty years of current profits at that price. High P/E means the market expects growth, low P/E means it expects trouble or boredom. P/E only compares fairly between companies in the same industry.', related: ['eps', 'market-cap', 'fundamental-analysis'], lesson: '/learn/m10-fundamentals-and-macro/03-valuation-basics' },
  { id: 'pennant', term: 'Pennant', short: 'A tiny symmetrical triangle forming right after a sharp move.', long: 'A pennant is a flag whose pause converges to a point instead of drifting in a channel. Same story, same measured target: the market rests briefly and then continues. Both patterns fail more often when the flagpole itself was driven by a one-off news spike.', related: ['flag', 'triangle', 'consolidation'], lesson: '/learn/m04-chart-patterns/05-flags-and-pennants' },
  { id: 'perpetual-futures', term: 'Perpetual Futures', short: 'Crypto futures contracts that never expire.', long: 'Because there is no expiry to force convergence, a funding payment between longs and shorts keeps the price anchored to spot. They offer high leverage and trade continuously, which makes them the main instrument on most crypto exchanges. They are also the main reason crypto traders get liquidated.', related: ['funding-rate', 'crypto', 'liquidation'], lesson: '/learn/m11-derivatives-and-other-markets/06-crypto' },
  { id: 'piercing-line', term: 'Piercing Line', short: 'A down candle followed by an up candle closing above the halfway point.', long: 'The second candle opens lower and then rallies to close more than fifty percent into the previous red body. If the red candle ran from 60 down to 56, a close above 58 qualifies. Anything less than halfway is considered a weak bounce rather than a reversal.', related: ['dark-cloud-cover', 'engulfing', 'confirmation'], lesson: '/learn/m02-candlestick-patterns/08-piercing-dark-cloud' },
  { id: 'pip', term: 'Pip', short: 'The standard smallest price step in a currency pair, usually 0.0001.', long: 'If EURUSD moves from 1.0850 to 1.0870, that is twenty pips. On a standard lot of 100,000 units, one pip is about ten dollars, so twenty pips is two hundred. Yen pairs are the exception, using the second decimal place instead of the fourth.', related: ['currency-pair', 'lot-size', 'forex'], lesson: '/learn/m11-derivatives-and-other-markets/05-forex' },
  { id: 'pivot-points', term: 'Pivot Points', short: 'Support and resistance levels calculated from the previous session high, low and close.', long: 'The central pivot is simply the average of those three prices, with R1, R2, S1 and S2 spaced around it. Because the formula is fixed, every trader using it sees exactly the same levels, which gives them weight. They are most popular with intraday futures and forex traders.', related: ['support', 'resistance', 'session'], lesson: '/learn/m05-indicators/13-pivot-points-and-ichimoku' },
  { id: 'position-sizing', term: 'Position Sizing', short: 'Calculating how many shares to buy from your stop distance and your risk budget.', long: 'Risk $200 with a stop two dollars away and you buy 100 shares; with a fifty cent stop you buy 400. The size comes from the maths, never from how confident you feel. This one calculation does more for survival than any indicator.', related: ['one-percent-rule', 'stop-loss', 'risk-management'], lesson: '/learn/m07-risk-management/02-the-one-percent-rule' },
  { id: 'position-trading', term: 'Position Trading', short: 'Holding trades for months, following the big trend.', long: 'Position traders use weekly charts, wide stops and small size, and ignore most of the daily noise. The approach demands patience and a tolerance for giving back open profit during pullbacks. It sits closest to investing while still being rule-based trading.', related: ['swing-trading', 'trend-following', 'timeframe'], lesson: '/learn/m09-strategies/01-trading-styles' },
  { id: 'pre-market', term: 'Pre-Market', short: 'Trading that happens before the official session opens, usually on thin volume.', long: 'Earnings and overnight news land here, so prices can move several percent before most people are awake. Spreads are wide and volume is low, which means a small order can push price further than it would at midday. Many beginners get their worst fills in this window.', related: ['after-hours', 'gap', 'session'], lesson: '/learn/m00-what-is-a-market/08-market-hours-and-sessions' },
  { id: 'premium', term: 'Premium', short: 'The price paid for an option contract.', long: 'Premium is made of intrinsic value, the part that is already profitable, plus extrinsic value, the part that is hope and time. A $5 premium on a call that is $2 in the money means $3 is time value that will decay to nothing. Sellers collect premium and take on the obligation in return.', related: ['intrinsic-value', 'extrinsic-value', 'theta'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'profit-factor', term: 'Profit Factor', short: 'Gross profit divided by gross loss: how many dollars you win per dollar lost.', long: 'Make $9,000 and lose $6,000 and your profit factor is 1.5. Anything above 1 is profitable, above 1.5 is solid, and anything above 3 on a small sample usually means the sample is too small. It is the quickest health check on a trading record.', related: ['expectancy', 'win-rate', 'equity-curve'], lesson: '/learn/m12-becoming-consistent/02-performance-metrics' },
  { id: 'prop-firm', term: 'Prop Firm', short: 'A company that funds traders to trade its capital for a share of profits.', long: 'Most modern retail prop firms run a paid evaluation with profit targets and strict drawdown limits. The rules, especially daily loss limits, are what wash out the majority of applicants rather than the profit target. Read the fee structure carefully before treating one as a career path.', related: ['daily-loss-limit', 'drawdown', 'discipline'], lesson: '/learn/m12-becoming-consistent/04-choosing-a-broker' },
  { id: 'protective-put', term: 'Protective Put', short: 'Buying a put on shares you own, as insurance against a fall.', long: 'Own the stock at 100 and buy a 90 put for $2, and your worst case becomes a loss of about $12 per share. Like all insurance, it costs money every time and usually expires unused. It is most sensible around known event risk rather than as a permanent policy.', related: ['put-option', 'premium', 'risk-management'], lesson: '/learn/m11-derivatives-and-other-markets/03-basic-options-strategies' },
  { id: 'pullback', term: 'Pullback', short: 'A small move against the trend that offers a better entry price.', long: 'Buying a pullback in an uptrend means waiting for the rest instead of chasing the run. Common places to look are a moving average, a Fibonacci level, or old resistance turned support. The stop sits below the pullback low, which usually gives a tighter risk than a breakout entry.', related: ['retracement', 'role-reversal', 'higher-low'], lesson: '/learn/m09-strategies/04-pullback-trading' },
  { id: 'pump-and-dump', term: 'Pump and Dump', short: 'A scam where promoters inflate a price with hype and sell into the buyers.', long: 'It thrives in thinly traded small caps and new crypto tokens, where a modest amount of buying moves the price sharply. The promotion looks like enthusiasm: urgent messages, screenshots of gains and a deadline. If someone is publicly begging you to buy, ask who is selling.', related: ['regulation', 'liquidity', 'fomo'], lesson: '/learn/m12-becoming-consistent/05-scams-and-red-flags' },
  { id: 'put-call-ratio', term: 'Put/Call Ratio', short: 'The volume of put options divided by the volume of calls, used to read fear.', long: 'A high ratio means traders are buying a lot of downside protection, which signals fear and sometimes a bottom. A very low ratio means complacency. Like all sentiment tools, it is a contrarian hint at extremes and noise in the middle.', related: ['sentiment', 'put-option', 'call-option'], lesson: '/learn/m10-fundamentals-and-macro/07-sentiment-vix-put-call' },
  { id: 'put-option', term: 'Put Option', short: 'The right to sell something at a fixed price before a set date.', long: 'Puts gain value when the underlying falls, which makes them the standard tool for hedging a portfolio. A 90 strike put bought for $2 breaks even at $88 and profits below that. Your maximum loss is the premium, which is what makes them safer than shorting outright.', related: ['call-option', 'protective-put', 'strike-price'], lesson: '/learn/m11-derivatives-and-other-markets/01-options-basics' },
  { id: 'r-multiple', term: 'R-Multiple', short: 'Measuring results in units of the amount you risked, instead of in money.', long: 'If you risk $150 and make $450, that is a 3R win, whatever the account size. Thinking in R makes trades on different instruments directly comparable and takes the emotion out of the numbers. A journal measured in R is far more useful than one measured in dollars.', related: ['risk-reward', 'expectancy', 'trading-journal'], lesson: '/learn/m07-risk-management/04-risk-reward-ratio' },
  { id: 'range', term: 'Range', short: 'A sideways market bouncing between a clear floor and a clear ceiling.', long: 'Markets spend a large part of their life going nowhere, and a range is that state drawn on a chart. Range traders sell near the top and buy near the bottom, with stops just beyond. The trap is that ranges end, and the last trade inside one is usually a loser.', related: ['consolidation', 'support', 'mean-reversion'], lesson: '/learn/m03-market-structure/05-ranges-and-consolidation' },
  { id: 'recency-bias', term: 'Recency Bias', short: 'Giving too much weight to what just happened and forgetting the longer record.', long: 'Three losses in a row make a solid strategy feel broken; three wins make a fragile one feel like genius. Both reactions come from a sample far too small to mean anything. A journal covering a hundred trades is the antidote to a memory covering three.', related: ['sample-size', 'trading-journal', 'confirmation-bias'], lesson: '/learn/m08-trading-psychology/04-cognitive-biases' },
  { id: 'rectangle', term: 'Rectangle', short: 'A sideways box with a flat top and flat bottom inside a bigger trend.', long: 'Price bounces between two horizontal lines, giving range traders repeated round trips and trend traders a level to wait for. Darvas boxes are the same idea used as a buy-the-breakout framework. The height of the box is projected from the break for a target.', related: ['range', 'breakout', 'measured-move'], lesson: '/learn/m04-chart-patterns/07-rectangles-and-boxes' },
  { id: 'regulation', term: 'Regulation', short: 'The official oversight that determines how safe your broker actually is.', long: 'Regulators such as the SEC, FCA or SEBI set capital rules, segregate client money and provide compensation schemes. An unregulated offshore broker offering 500 to 1 leverage is offering you a risk far larger than the market itself. Checking the licence number on the regulator website takes two minutes.', related: ['broker', 'pump-and-dump', 'settlement'], lesson: '/learn/m12-becoming-consistent/04-choosing-a-broker' },
  { id: 'resistance', term: 'Resistance', short: 'A price area where sellers have repeatedly stepped in and capped a rise.', long: 'Resistance forms where earlier buyers are trapped and want to exit at breakeven, and where sellers left unfilled orders. It behaves like a ceiling until enough demand arrives to break through. Once broken, it often becomes support on the way back down.', related: ['support', 'supply-zone', 'role-reversal'], lesson: '/learn/m03-market-structure/03-support-and-resistance' },
  { id: 'retest', term: 'Retest', short: 'Price returning to touch a broken level before continuing in the new direction.', long: 'After breaking 75, a stock often drifts back to about 75 and then resumes higher. Entering on the retest gives you a tighter stop and a clearer invalidation point than chasing the breakout candle. The cost is that strong moves sometimes never come back.', related: ['breakout', 'role-reversal', 'pullback'], lesson: '/learn/m03-market-structure/06-breakouts-and-fakeouts' },
  { id: 'retracement', term: 'Retracement', short: 'A temporary move back against the trend before it resumes.', long: 'A retracement is a pause, not a reversal: the trend structure stays intact. Shallow retracements of around 38% suggest strong demand, while deep ones past 61.8% put the trend in question. Distinguishing a retracement from a reversal in real time is the hardest part of trend trading.', related: ['pullback', 'fibonacci', 'higher-low'], lesson: '/learn/m05-indicators/12-fibonacci' },
  { id: 'revenge-trading', term: 'Revenge Trading', short: 'Trading immediately after a loss to win the money back.', long: 'The market does not know you lost and owes you nothing, but your brain treats the loss as an insult to be corrected. Revenge trades are bigger, faster and less planned, which is why they escalate. A daily loss limit and a mandatory break are the standard defences.', related: ['tilt', 'daily-loss-limit', 'discipline'], lesson: '/learn/m08-trading-psychology/03-revenge-trading' },
  { id: 'revenue', term: 'Revenue', short: 'The total money a company took in before any costs are subtracted.', long: 'Also called the top line, because it sits at the top of the income statement. Revenue growth shows whether the business is actually expanding, while profit can be massaged by cost cuts. A company can grow revenue for years and still never earn a profit.', related: ['earnings', 'eps', 'cash-flow'], lesson: '/learn/m10-fundamentals-and-macro/02-earnings-and-financial-statements' },
  { id: 'risk-management', term: 'Risk Management', short: 'Deciding how much you can lose before you think about what you could win.', long: 'It covers position size, stop placement, how many trades you hold at once and when you stop for the day. It is the only part of trading you fully control, which is why professionals treat it as the job. Most blown accounts are not caused by bad analysis but by good analysis sized wrongly.', related: ['position-sizing', 'stop-loss', 'drawdown'], lesson: '/learn/m07-risk-management/01-why-risk-first' },
  { id: 'risk-of-ruin', term: 'Risk of Ruin', short: 'The probability that a losing streak wipes out your account entirely.', long: 'It depends on your edge, your win rate and above all your position size. Risking 2% per trade makes a twenty-loss streak survivable; risking 20% makes a five-loss streak fatal. Since streaks are guaranteed over enough trades, this number is really a sizing question.', related: ['one-percent-rule', 'drawdown', 'martingale'], lesson: '/learn/m07-risk-management/07-drawdown-and-risk-of-ruin' },
  { id: 'risk-reward', term: 'Risk to Reward', short: 'How much you stand to gain compared with how much you are risking.', long: 'Risking $100 to make $300 is a 1:3 ratio. A good ratio lets you be wrong more often than right and still finish ahead, but only if the target is realistic. Inflating the target to make the ratio look better is self-deception, not planning.', related: ['r-multiple', 'expectancy', 'take-profit'], lesson: '/learn/m07-risk-management/04-risk-reward-ratio' },
  { id: 'role-reversal', term: 'Role Reversal', short: 'Broken resistance turning into support, and broken support into resistance.', long: 'The level that used to cap price becomes the floor once enough buyers have accepted the higher price. It happens because the people who sold there now want back in, and the people who bought the break defend their entry. Most good pullback entries are role reversal entries.', related: ['support', 'resistance', 'retest'], lesson: '/learn/m03-market-structure/07-role-reversal' },
  { id: 'rollover', term: 'Rollover', short: 'Closing an expiring contract and opening the next month to stay in the trade.', long: 'Futures expire, so a trader who wants continued exposure must roll, usually a week or so before the date. The two contracts trade at different prices, which creates a small gap on continuous charts. Forgetting to roll can result in an unwanted settlement or forced closure.', related: ['expiry', 'contango', 'futures-contract'], lesson: '/learn/m11-derivatives-and-other-markets/04-futures' },
  { id: 'rotation', term: 'Sector Rotation', short: 'Money moving out of one group of stocks and into another.', long: 'Defensive sectors like utilities attract money when investors turn cautious; technology and consumer names lead when optimism returns. Watching which sectors lead often warns you about the market mood before the index itself moves. It is a slow signal, best read on weekly charts.', related: ['sector', 'sentiment', 'index'], lesson: '/learn/m10-fundamentals-and-macro/06-sectors-and-rotation' },
  { id: 'rsi', term: 'RSI', short: 'A 0 to 100 momentum gauge comparing average gains to average losses.', long: 'The Relative Strength Index defaults to 14 periods, with 70 and 30 as the traditional extremes. Above 70 is not a sell signal: in a strong trend RSI can sit above 70 for weeks. Its most respected use is divergence, where price makes a new high and RSI does not.', related: ['overbought', 'oversold', 'divergence'], lesson: '/learn/m05-indicators/04-rsi' },
  { id: 'sample-size', term: 'Sample Size', short: 'How many trades you have taken before judging whether something works.', long: 'Ten trades tell you almost nothing, because luck dominates at that scale. Most traders want at least one hundred trades of the same setup before drawing conclusions. Small samples are why people abandon good strategies and fall in love with bad ones.', related: ['expectancy', 'backtesting', 'recency-bias'], lesson: '/learn/m09-strategies/09-backtesting-and-forward-testing' },
  { id: 'scalping', term: 'Scalping', short: 'Taking many tiny trades that last seconds or minutes.', long: 'Scalpers aim for a few ticks per trade and rely on very tight spreads and low commissions to survive. The style demands constant attention, fast execution and a temperament that shrugs off a dozen small losses an hour. Costs matter more here than in any other style.', related: ['day-trading', 'spread', 'level-2'], lesson: '/learn/m09-strategies/01-trading-styles' },
  { id: 'sector', term: 'Sector', short: 'A group of companies doing similar business, such as energy or healthcare.', long: 'Stocks in the same sector tend to move together, which is both a research shortcut and a hidden risk. Comparing a company to its sector tells you whether it is genuinely strong or just floating on a rising tide. Sector performance is also a clue to where the economic cycle sits.', related: ['rotation', 'correlation', 'index'], lesson: '/learn/m10-fundamentals-and-macro/06-sectors-and-rotation' },
  { id: 'sentiment', term: 'Market Sentiment', short: 'The overall mood of participants: how greedy or fearful the crowd is.', long: 'Sentiment is measured with surveys, the VIX, put/call ratios and positioning data. It is most useful at extremes, because unanimous opinion means everyone has already traded on it. Universal panic has marked more bottoms than any indicator ever has.', related: ['vix', 'put-call-ratio', 'fear'], lesson: '/learn/m10-fundamentals-and-macro/07-sentiment-vix-put-call' },
  { id: 'session', term: 'Session', short: 'The block of hours when a particular market is officially open.', long: 'The US stock session runs 9:30am to 4:00pm New York time; London, Tokyo and Sydney each have their own. Volume and volatility cluster at the open and close, and sag in the middle of the day. Choosing which session you trade shapes your whole routine.', related: ['pre-market', 'after-hours', 'volume'], lesson: '/learn/m00-what-is-a-market/08-market-hours-and-sessions' },
  { id: 'settlement', term: 'Settlement', short: 'The delay between a trade being agreed and the cash and shares changing hands.', long: 'Stock markets commonly settle one business day after the trade, written as T+1. Until settlement, some account types restrict reusing the proceeds, which is how beginners run into good faith violations. Knowing your settlement rules avoids surprise restrictions on your account.', related: ['broker', 'commission', 'regulation'], lesson: '/learn/m06-orders-and-execution/09-fees-commissions-settlement' },
  { id: 'setup', term: 'Setup', short: 'The specific chart conditions that must be present before you consider a trade.', long: 'A setup might be: daily uptrend, pullback to the 20 EMA, bullish engulfing candle on the hourly chart. Defining it precisely lets you count how often it appears and how it performs. If you cannot describe your setup in one sentence, you do not have one yet.', related: ['trading-plan', 'edge', 'confirmation'], lesson: '/learn/m09-strategies/08-building-a-trading-plan' },
  { id: 'share', term: 'Share', short: 'One unit of ownership in a company.', long: 'If a company has issued one million shares and you hold one thousand, you own one tenth of one percent of it. That slice entitles you to a share of the profits and usually a vote. Shares exist because a business can raise money faster by selling small pieces to many people than by borrowing.', related: ['stock', 'market-cap', 'earnings'], lesson: '/learn/m00-what-is-a-market/02-what-is-a-stock' },
  { id: 'sharpe-ratio', term: 'Sharpe Ratio', short: 'A measure of return compared with how bumpy the ride was.', long: 'It divides return above the risk-free rate by the volatility of those returns. A Sharpe of 1 is respectable, 2 is very good, and anything much higher on a retail account usually reflects luck or a short sample. It rewards steadiness rather than spectacular single months.', related: ['max-drawdown', 'equity-curve', 'profit-factor'], lesson: '/learn/m12-becoming-consistent/02-performance-metrics' },
  { id: 'shooting-star', term: 'Shooting Star', short: 'A small body at the bottom with a long upper wick, appearing after a rise.', long: 'Price spiked up during the period and gave all of it back, leaving a long tail pointing at the failed high. If a stock rallies from 80 to 86 and closes at 80.50, that six dollar wick marks where sellers were waiting. It is one of the clearest pictures of rejection on a chart.', related: ['inverted-hammer', 'gravestone-doji', 'resistance'], lesson: '/learn/m02-candlestick-patterns/04-shooting-star-inverted-hammer' },
  { id: 'short', term: 'Short', short: 'Betting on a fall by selling something you do not own, then buying it back.', long: 'The profit and loss is reversed: you gain when price falls and lose when it rises. Because price can rise without limit, the risk of a short has no natural ceiling. That asymmetry is why shorting demands tighter discipline than going long.', related: ['short-selling', 'short-squeeze', 'margin'], lesson: '/learn/m06-orders-and-execution/05-going-long-and-short' },
  { id: 'short-selling', term: 'Short Selling', short: 'Borrowing shares, selling them, and buying them back later to return them.', long: 'Your broker lends you the shares, usually for a fee, and you owe them back regardless of the price. Sell 100 shares at 50 and buy them back at 40 and you keep $1,000 minus costs. If the lender recalls the shares you can be forced to close at the worst possible time.', related: ['short', 'margin', 'short-squeeze'], lesson: '/learn/m06-orders-and-execution/05-going-long-and-short' },
  { id: 'short-squeeze', term: 'Short Squeeze', short: 'A sharp rally caused by short sellers being forced to buy back at once.', long: 'When a heavily shorted stock rises, losses force shorts to cover, and their buying pushes price higher, forcing more of them out. The feedback loop can produce moves of hundreds of percent that have nothing to do with the business. Crowded shorts are dangerous even when the analysis is right.', related: ['short-selling', 'liquidation', 'volatility'], lesson: '/learn/m06-orders-and-execution/05-going-long-and-short' },
  { id: 'slippage', term: 'Slippage', short: 'The difference between the price you expected and the price you actually got.', long: 'You click buy at 20.00 and fill at 20.04: four cents of slippage. It grows with order size, shrinks with liquidity, and explodes around news. A strategy that looks profitable in a backtest can die entirely from slippage once it meets the real market.', related: ['fill', 'liquidity', 'market-order'], lesson: '/learn/m06-orders-and-execution/07-slippage-and-liquidity' },
  { id: 'sma', term: 'Simple Moving Average', short: 'The plain average of the last N closing prices, redrawn each candle.', long: 'A 20-period SMA adds the last twenty closes and divides by twenty. Every one of those closes counts equally, so a single old spike keeps distorting the line until it drops out of the window. The 50 and 200 SMAs are watched by enough people to become self-fulfilling levels.', related: ['ema', 'wma', 'moving-average'], lesson: '/learn/m05-indicators/02-moving-averages' },
  { id: 'spinning-top', term: 'Spinning Top', short: 'A small body with wicks on both sides, showing a period of confusion.', long: 'Neither side achieved anything: price wandered up and down and finished near the open. One spinning top is noise, but a cluster of them means the market has gone quiet and is probably coiling. Traders often stand aside during them and wait for a decisive candle.', related: ['doji', 'marubozu', 'consolidation'], lesson: '/learn/m02-candlestick-patterns/05-marubozu-spinning-top' },
  { id: 'spread', term: 'Spread', short: 'The gap between the best bid and the best ask price.', long: 'If the bid is 100.00 and the ask is 100.05, the spread is five cents, and that is your instant cost of entering. Heavily traded shares have spreads of a cent or less; thin small caps can have spreads of one percent or more. Scalpers live and die by this number because they pay it many times a day.', related: ['bid', 'ask', 'liquidity'], lesson: '/learn/m00-what-is-a-market/07-bid-ask-spread' },
  { id: 'squeeze', term: 'Squeeze', short: 'A period when Bollinger Bands narrow sharply, signalling stored-up volatility.', long: 'Quiet markets do not stay quiet, so a very tight band width often precedes a large move. The squeeze tells you something is coming but says nothing about the direction. Traders usually combine it with structure to decide which side to take.', related: ['bollinger-bands', 'consolidation', 'breakout'], lesson: '/learn/m05-indicators/07-bollinger-bands' },
  { id: 'stochastic', term: 'Stochastic Oscillator', short: 'A 0 to 100 gauge of where the close sits inside the recent high-low range.', long: 'If the last 14 candles ranged from 40 to 50 and price closed at 49, stochastic reads 90: closing near the top of the range. Readings above 80 and below 20 are the classic extremes. It fires far more often than RSI, which makes it popular for ranges and painful in trends.', related: ['rsi', 'oscillator', 'overbought'], lesson: '/learn/m05-indicators/06-stochastic' },
  { id: 'stock', term: 'Stock', short: 'The general word for company ownership traded on an exchange.', long: 'In everyday speech stock and share are used interchangeably: you buy stock in a company by buying its shares. A stock is a claim on a real business with real revenue, not just a ticker that wiggles. Remembering that keeps you from treating the chart as a slot machine.', related: ['share', 'earnings', 'fundamental-analysis'], lesson: '/learn/m00-what-is-a-market/02-what-is-a-stock' },
  { id: 'stop-limit-order', term: 'Stop-Limit Order', short: 'A stop order that turns into a limit order instead of a market order.', long: 'You set two prices, for example a stop at 48 and a limit at 47.80, so you will not be filled below 47.80. That protects you from a terrible fill and exposes you to a worse risk: no fill at all while price collapses. For protective exits, most traders prefer a plain stop.', related: ['stop-order', 'limit-order', 'gap'], lesson: '/learn/m06-orders-and-execution/02-stop-orders' },
  { id: 'stop-loss', term: 'Stop Loss', short: 'The price at which you accept the trade was wrong and get out.', long: 'A stop is not a prediction, it is a budget: it defines the most you are willing to pay to find out if you were right. Placing it below structure, or an ATR beyond it, works better than placing it at a round number of dollars. Trading without one means your worst trade decides your career.', related: ['stop-order', 'position-sizing', 'atr'], lesson: '/learn/m07-risk-management/03-stop-loss-placement' },
  { id: 'stop-order', term: 'Stop Order', short: 'A resting order that becomes a market order once a trigger price is touched.', long: 'A sell stop at 48 sits dormant while price is above it and fires the moment 48 trades. Because it turns into a market order, the fill can be worse than the trigger in a fast move. It is the standard way to automate an exit you do not want to think about twice.', related: ['stop-limit-order', 'stop-loss', 'slippage'], lesson: '/learn/m06-orders-and-execution/02-stop-orders' },
  { id: 'strike-price', term: 'Strike Price', short: 'The fixed price at which an option can be exercised.', long: 'It is the reference point for everything: whether the option is in or out of the money, and how much it costs. Strikes near the current price cost the most because they are most likely to matter. Choosing a far strike is cheap and usually expires worthless.', related: ['call-option', 'in-the-money', 'out-of-the-money'], lesson: '/learn/m11-derivatives-and-other-markets/01-options-basics' },
  { id: 'sunk-cost', term: 'Sunk Cost Fallacy', short: 'Staying in a losing trade because of what you have already lost in it.', long: 'The money spent is gone whatever you do next, so it should have no weight in the decision. The useful question is whether you would open this position today at this price. If the answer is no, the only reason you are still in it is the sunk cost.', related: ['loss-aversion', 'averaging-down', 'stop-loss'], lesson: '/learn/m08-trading-psychology/04-cognitive-biases' },
  { id: 'supply-zone', term: 'Supply Zone', short: 'An area where heavy selling previously appeared and may appear again.', long: 'Instead of one line, you mark the whole area where price turned sharply lower, usually the base of the candles before the drop. The idea is that large sellers could not fill their entire order and left the rest waiting. Zones are more forgiving than lines because real markets overshoot.', related: ['demand-zone', 'resistance', 'distribution'], lesson: '/learn/m03-market-structure/08-supply-and-demand-zones' },
  { id: 'support', term: 'Support', short: 'A price area where buyers have repeatedly stepped in and stopped a fall.', long: 'Support is a zone, not a razor-thin line, because memory is fuzzy and stops cluster. If a stock bounced from about 48 three times, that region is support until a candle closes decisively below it. The more touches and the more volume, the more traders are watching it.', related: ['resistance', 'demand-zone', 'role-reversal'], lesson: '/learn/m03-market-structure/03-support-and-resistance' },
  { id: 'swing-high', term: 'Swing High', short: 'A candle high with lower highs on both sides of it: a local peak.', long: 'A common rule is that a swing high needs at least two candles on each side with lower highs. Marking them consistently is what turns a squiggly chart into readable structure. Swing highs become resistance and are natural stop-loss locations for short trades.', related: ['swing-low', 'higher-high', 'resistance'], lesson: '/learn/m03-market-structure/02-swing-highs-and-lows' },
  { id: 'swing-low', term: 'Swing Low', short: 'A candle low with higher lows on both sides of it: a local trough.', long: 'Swing lows anchor Fibonacci retracements, trendlines and stop placements. Using the same definition every time is more valuable than using the perfect definition. If you move your swing points to fit your opinion, your analysis becomes decoration.', related: ['swing-high', 'higher-low', 'support'], lesson: '/learn/m03-market-structure/02-swing-highs-and-lows' },
  { id: 'swing-trading', term: 'Swing Trading', short: 'Holding trades for several days to a few weeks to capture one move.', long: 'Swing trading fits people with jobs: you analyse in the evening, place orders and let them work. You accept overnight and weekend gap risk in exchange for larger targets and fewer decisions. The four-hour and daily charts are the usual home.', related: ['day-trading', 'position-trading', 'pullback'], lesson: '/learn/m09-strategies/01-trading-styles' },
  { id: 'take-profit', term: 'Take Profit', short: 'A resting order that closes a winning trade at a chosen price.', long: 'Deciding your target in advance stops you from turning a good trade into a round trip. Many traders scale out, selling half at one target and trailing the rest. Wherever you place it, the target should be based on structure, not on the amount of money you would like to make.', related: ['stop-loss', 'measured-move', 'risk-reward'], lesson: '/learn/m06-orders-and-execution/03-bracket-and-oco' },
  { id: 'tasuki-gap', term: 'Tasuki Gap', short: 'A gap in the trend direction followed by a partial pullback that does not fill it.', long: 'Price gaps up, the next candle pulls back into the gap but closes without filling it, and the trend resumes. The unfilled gap is the point: buyers defended it. If the gap does get filled, the pattern is void and the message flips.', related: ['gap', 'window', 'three-methods'], lesson: '/learn/m02-candlestick-patterns/14-continuation-patterns' },
  { id: 'technical-analysis', term: 'Technical Analysis', short: 'Studying price and volume history to judge what is likely to happen next.', long: 'It assumes that everything known is already in the price and that human behaviour repeats in recognisable shapes. Technicals give you precise entries, stops and targets, which fundamentals cannot. They tell you nothing about whether a company is about to go bankrupt.', related: ['fundamental-analysis', 'indicator', 'support'], lesson: '/learn/m10-fundamentals-and-macro/01-technical-vs-fundamental' },
  { id: 'theta', term: 'Theta', short: 'How much value an option loses each day simply because time passed.', long: 'A theta of minus 0.05 costs the holder about five cents a day, accelerating as expiry nears. Buyers pay theta; sellers collect it, which is why selling premium is popular. Theta is the reason a correct directional call can still lose money if it takes too long.', related: ['extrinsic-value', 'expiry', 'covered-call'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'three-black-crows', term: 'Three Black Crows', short: 'Three strong down candles in a row, each closing near its low.', long: 'The bearish twin of three white soldiers, and a classic sign that a rally has broken. Three consecutive decisive red closes rarely happen by accident in a healthy uptrend. The risk in trading it is that price is already well below the top by the time it completes.', related: ['three-white-soldiers', 'downtrend', 'momentum'], lesson: '/learn/m02-candlestick-patterns/11-three-soldiers-three-crows' },
  { id: 'three-methods', term: 'Rising and Falling Three Methods', short: 'A big trend candle, three small pauses, then another big candle the same way.', long: 'This is a continuation pattern: the small candles stay inside the range of the first big one, showing a rest rather than a fight. When the fifth candle breaks out in the original direction, the trend has effectively refuelled. It is the candlestick version of a flag.', related: ['flag', 'tasuki-gap', 'consolidation'], lesson: '/learn/m02-candlestick-patterns/14-continuation-patterns' },
  { id: 'three-white-soldiers', term: 'Three White Soldiers', short: 'Three strong up candles in a row, each closing near its high.', long: 'Each candle opens within the previous body and closes above the previous close, building a staircase. It shows steady, repeated buying rather than one panic spike. After a long decline it often marks a genuine change of control, though by the third candle you are already buying strength.', related: ['three-black-crows', 'momentum', 'marubozu'], lesson: '/learn/m02-candlestick-patterns/11-three-soldiers-three-crows' },
  { id: 'tick-size', term: 'Tick Size', short: 'The smallest price increment an instrument can move.', long: 'US shares tick in cents, the E-mini S&P moves in 0.25 index points, and many currency futures use even smaller steps. You cannot place an order between ticks. Knowing the tick size is the first step to knowing what a one-tick move costs you.', related: ['tick-value', 'futures-contract', 'pip'], lesson: '/learn/m11-derivatives-and-other-markets/04-futures' },
  { id: 'tick-value', term: 'Tick Value', short: 'How much money one tick of movement is worth per contract.', long: 'On the E-mini S&P, one 0.25 point tick is worth $12.50, so four ticks is $50. Multiply tick value by your stop distance in ticks and you have your risk per contract. Getting this wrong is how new futures traders take positions ten times larger than intended.', related: ['tick-size', 'futures-contract', 'position-sizing'], lesson: '/learn/m11-derivatives-and-other-markets/04-futures' },
  { id: 'ticker', term: 'Ticker Symbol', short: 'The short code that names an instrument, like AAPL for Apple.', long: 'Every tradable thing has a ticker so that orders are never ambiguous. Stocks use letters (TSLA), forex uses pairs (EURUSD), futures add a month and year code. Tickers are only unique within a market, so the same letters can mean different companies in different countries.', related: ['share', 'stock', 'currency-pair'], lesson: '/learn/m00-what-is-a-market/09-tickers-lots-and-units' },
  { id: 'tilt', term: 'Tilt', short: 'An emotional state, borrowed from poker, where you stop following your own rules.', long: 'On tilt, position sizes creep up, stops get widened and setups get invented. It can follow a big loss or a big win, because both raise your heart rate. Recognising the physical symptoms early, and walking away, is a skill worth practising deliberately.', related: ['revenge-trading', 'discipline', 'daily-loss-limit'], lesson: '/learn/m08-trading-psychology/03-revenge-trading' },
  { id: 'time-in-force', term: 'Time in Force', short: 'How long an order stays alive before the broker cancels it.', long: 'DAY expires at the close, GTC waits for months, IOC fills what it can right now and kills the rest, FOK demands everything at once or nothing. Choosing wrongly can leave a forgotten order waiting to ambush you weeks later. Always check the default your platform uses.', related: ['gtc', 'order', 'fill'], lesson: '/learn/m06-orders-and-execution/04-time-in-force' },
  { id: 'timeframe', term: 'Timeframe', short: 'How much time each candle on your chart represents.', long: 'On a 5-minute chart each candle covers five minutes; on a daily chart each covers a whole session. One regular US trading day contains 78 five-minute candles, and all of them collapse into a single daily candle. Shorter timeframes mean more signals, more noise and more decisions.', related: ['multi-timeframe', 'candlestick', 'scalping'], lesson: '/learn/m01-reading-price/05-timeframes' },
  { id: 'trading-journal', term: 'Trading Journal', short: 'A record of every trade with the reason, the result and what you learned.', long: 'Log the setup, entry, stop, target, size, outcome in R, and one honest sentence about your state of mind. After fifty trades, patterns appear that you would never notice from memory alone. It is the single highest-return habit available to a developing trader.', related: ['r-multiple', 'discipline', 'sample-size'], lesson: '/learn/m12-becoming-consistent/01-the-trading-journal' },
  { id: 'trading-plan', term: 'Trading Plan', short: 'A written document defining what you trade, when, how big and when you stop.', long: 'A complete plan covers setup, entry trigger, stop, target, size, trade management and review schedule. Writing it down turns vague intentions into rules that can be tested and improved. If it is not written, it changes every time the market makes you nervous.', related: ['setup', 'discipline', 'backtesting'], lesson: '/learn/m09-strategies/08-building-a-trading-plan' },
  { id: 'trailing-stop', term: 'Trailing Stop', short: 'A stop that automatically follows price at a fixed distance as the trade wins.', long: 'Set a one dollar trail and the stop rises with every new high but never falls back. It is a mechanical way to let winners run while protecting gains. The catch is choosing the distance: too tight and normal noise ends the trade, too wide and you hand back most of the profit.', related: ['stop-order', 'atr', 'take-profit'], lesson: '/learn/m06-orders-and-execution/02-stop-orders' },
  { id: 'trend', term: 'Trend', short: 'The general direction price has been travelling over your chosen timeframe.', long: 'A trend is defined by structure, not by feeling: rising peaks and troughs mean up, falling peaks and troughs mean down, and anything else is sideways. Trends exist on every timeframe at once, so a stock can be in a daily uptrend and a five-minute downtrend. Naming the trend is the first step of every analysis.', related: ['uptrend', 'downtrend', 'range'], lesson: '/learn/m03-market-structure/01-trends' },
  { id: 'trend-following', term: 'Trend Following', short: 'Buying strength and selling weakness, aiming to ride long moves.', long: 'Trend followers accept a low win rate, often under 40%, because a few very large winners pay for many small losses. The discipline is in taking every signal, since skipping the wrong one removes the trade that funds the year. It performs badly in long sideways markets.', related: ['markup', 'mean-reversion', 'expectancy'], lesson: '/learn/m09-strategies/03-trend-following' },
  { id: 'trendline', term: 'Trendline', short: 'A straight line drawn along successive swing lows or highs to show a trend.', long: 'An honest trendline connects at least two points and gets validated by a third touch. Drawn well it frames the rhythm of a move; drawn badly it is just a line that agrees with your opinion. If you had to squint or skip a candle to make it fit, redraw it.', related: ['channel', 'swing-low', 'log-scale'], lesson: '/learn/m03-market-structure/04-trendlines-and-channels' },
  { id: 'triangle', term: 'Triangle', short: 'A pattern where price swings get smaller, coiling towards a breakout.', long: 'Ascending triangles have a flat top and rising lows, descending ones a flat floor and falling highs, and symmetrical ones squeeze from both sides. The narrowing range means volatility is being stored, not destroyed. Most traders wait for the close outside the lines rather than guessing the direction.', related: ['wedge', 'consolidation', 'breakout'], lesson: '/learn/m04-chart-patterns/04-triangles' },
  { id: 'tweezer', term: 'Tweezer Top or Bottom', short: 'Two or more candles sharing almost exactly the same high or low.', long: 'Matching extremes show a level being defended twice in a row, which is more convincing than a single touch. Tweezer bottoms at support and tweezer tops at resistance are simple, visual and easy for beginners to spot. They work best when the second candle opposes the first in colour.', related: ['support', 'resistance', 'double-top'], lesson: '/learn/m02-candlestick-patterns/09-tweezers-and-counterattack' },
  { id: 'uptrend', term: 'Uptrend', short: 'A sequence of higher highs and higher lows.', long: 'Each rally exceeds the last peak and each pullback stops above the last trough. The uptrend stays intact until a pullback breaks below the previous low, which is your objective signal that something changed. Trading with the uptrend means buying the pullbacks, not the peaks.', related: ['higher-high', 'higher-low', 'downtrend'], lesson: '/learn/m03-market-structure/01-trends' },
  { id: 'vega', term: 'Vega', short: 'How much an option price changes when implied volatility changes.', long: 'A vega of 0.10 means the option gains ten cents for each one point rise in implied volatility. It explains why options get expensive before earnings and cheap afterwards. Buying high-vega options into a known event is often a losing trade even when direction is right.', related: ['implied-volatility', 'iv-crush', 'premium'], lesson: '/learn/m11-derivatives-and-other-markets/02-options-pricing-and-greeks' },
  { id: 'vix', term: 'VIX', short: 'An index of expected stock market volatility, nicknamed the fear gauge.', long: 'It is derived from option prices on the S&P 500 and shows the size of the moves traders are paying to protect against. Below 15 suggests calm, above 30 suggests real stress. It usually spikes when shares fall, which is why it is used as a hedge.', related: ['sentiment', 'implied-volatility', 'volatility'], lesson: '/learn/m10-fundamentals-and-macro/07-sentiment-vix-put-call' },
  { id: 'volatility', term: 'Volatility', short: 'How much and how fast a price moves around, in either direction.', long: 'Volatility is not the same as direction: a market can be violently volatile and end the week unchanged. It decides how wide your stop must be and therefore how small your position must be. A stock that swings three dollars a day needs a very different plan from one that swings thirty cents.', related: ['atr', 'implied-volatility', 'position-sizing'], lesson: '/learn/m05-indicators/08-atr' },
  { id: 'volume', term: 'Volume', short: 'How many shares or contracts changed hands during a period.', long: 'Volume is the attendance figure for a price move. A breakout on triple the usual volume means real money committed; the same breakout on quiet volume is often a drift that fades. Most charting platforms draw it as bars under the price panel.', related: ['obv', 'volume-profile', 'breakout'], lesson: '/learn/m01-reading-price/06-volume' },
  { id: 'volume-profile', term: 'Volume Profile', short: 'A histogram showing how much volume traded at each price level.', long: 'Instead of volume per candle, it shows volume per price, revealing the levels where the market spent most of its energy. High volume nodes act like magnets and low volume gaps are crossed quickly. The single busiest price is called the point of control.', related: ['volume', 'support', 'range'], lesson: '/learn/m05-indicators/10-volume-indicators' },
  { id: 'vwap', term: 'VWAP', short: 'The volume weighted average price paid so far in the session.', long: 'VWAP resets each day and weights every trade by its size, so it shows where the bulk of the money actually changed hands. Institutions use it as a benchmark for whether they executed well. Intraday traders treat price above VWAP as bullish control and price below as bearish.', related: ['volume', 'session', 'overlay'], lesson: '/learn/m05-indicators/09-vwap' },
  { id: 'walk-forward', term: 'Walk-Forward Testing', short: 'Optimising on one slice of history and testing on the next, repeatedly.', long: 'You tune the rules on 2019, test them untouched on 2020, then roll the window forward and repeat. If performance holds up on each unseen slice, the edge is more likely to be real. It is the most practical defence against overfitting available to an individual.', related: ['overfitting', 'backtesting', 'forward-testing'], lesson: '/learn/m09-strategies/09-backtesting-and-forward-testing' },
  { id: 'wedge', term: 'Wedge', short: 'Two converging lines that both slope the same way, often a reversal.', long: 'A rising wedge slopes up while narrowing, and usually resolves downward; a falling wedge does the opposite. The narrowing shows that each push is smaller than the last, meaning momentum is fading even though price still advances. Wedges are the pattern most often confused with a healthy trend.', related: ['triangle', 'divergence', 'pullback'], lesson: '/learn/m04-chart-patterns/06-wedges' },
  { id: 'wick', term: 'Wick', short: 'The thin line above or below the body, showing prices that were rejected.', long: 'A long upper wick means buyers pushed price up and were beaten back before the close; a long lower wick means the opposite. Wicks are the memory of failed attempts, which is why candles with huge wicks appear at turning points. Also called shadows or tails.', related: ['body', 'hammer', 'shooting-star'], lesson: '/learn/m01-reading-price/03-anatomy-of-a-candle' },
  { id: 'win-rate', term: 'Win Rate', short: 'The percentage of your trades that end in a profit.', long: 'A high win rate feels wonderful and proves nothing on its own: you can win 90% of the time and still go broke if the losses are huge. Win rate only means something alongside average win and average loss. Trend followers routinely run below 45% and make money anyway.', related: ['expectancy', 'risk-reward', 'profit-factor'], lesson: '/learn/m07-risk-management/06-win-rate-vs-rr' },
  { id: 'window', term: 'Window', short: 'The Japanese candlestick name for a gap between two candles.', long: 'Traditional candlestick theory says windows act as support or resistance: an upward window should hold price up on the way back down. The saying is that windows tend to be closed eventually, meaning gaps get filled. Treat the level as a zone to watch, not a guarantee.', related: ['gap', 'tasuki-gap', 'support'], lesson: '/learn/m02-candlestick-patterns/14-continuation-patterns' },
  { id: 'wma', term: 'Weighted Moving Average', short: 'A moving average where weights fall in a straight line as prices get older.', long: 'In a 5-period WMA the newest close is multiplied by five, the next by four, and so on down to one. It sits between the SMA and the EMA in responsiveness. It is less common than the other two, but it turns up inside other tools such as the Hull moving average.', related: ['sma', 'ema', 'moving-average'], lesson: '/learn/m05-indicators/02-moving-averages' },
  { id: 'wyckoff', term: 'Wyckoff Cycle', short: 'A model describing markets as four repeating phases of buying and selling.', long: 'Richard Wyckoff taught that price passes through accumulation, markup, distribution and markdown, driven by large operators rather than by news. You do not need to trade his full method to benefit from asking which phase you are in. It is a map of context, not an entry signal.', related: ['accumulation', 'markup', 'distribution'], lesson: '/learn/m03-market-structure/09-market-cycles-wyckoff' },
  { id: 'yield', term: 'Yield', short: 'The annual return an investment pays, expressed as a percentage of its price.', long: 'A bond paying $30 a year priced at $1,000 yields three percent; if the price falls to $750 the yield rises to four. Bond yields and prices always move in opposite directions. Rising long-term yields tend to pressure high-growth shares the hardest.', related: ['interest-rate', 'central-bank', 'sector'], lesson: '/learn/m10-fundamentals-and-macro/04-interest-rates-and-central-banks' },
];

export const GLOSSARY_INDEX: Record<string, GlossaryEntry> = Object.fromEntries(GLOSSARY.map((g) => [g.id, g]));
